function isInstalledApp() {
  return (
    nativeBuild ||
    window.matchMedia("(display-mode: standalone)").matches ||
    navigator.standalone === true
  );
}

function updateInstallControl() {
  const button = $("#installAppButton");
  if (!button) return;
  const installed = isInstalledApp();
  const ios = /iPad|iPhone|iPod/.test(navigator.userAgent);
  button.disabled = installed;
  $("#installAppState").textContent = installed
    ? "Installed"
    : deferredInstallPrompt
      ? "Ready"
      : ios
        ? "How to"
        : "Options";
  $("#installAppHelp").textContent = installed
    ? "Mica is already installed on this device"
    : deferredInstallPrompt
      ? "Install with your browser’s secure app prompt"
      : ios
        ? "Use Safari’s Share menu, then Add to Home Screen"
        : "See the install steps supported by this browser";
}

function applyMotionPreference() {
  document.body.dataset.motion = motionPreference;
  const label = { auto: "Auto", reduce: "Reduce", full: "Full" }[
    motionPreference
  ];
  const help = {
    auto: "Follow your device preference · select to change",
    reduce: "Animations minimized on this device · select to change",
    full: "Use full interface motion · select to change",
  }[motionPreference];
  if ($("#motionState")) $("#motionState").textContent = label;
  if ($("#motionHelp")) $("#motionHelp").textContent = help;
}

function cycleMotionPreference() {
  const modes = ["auto", "reduce", "full"];
  motionPreference =
    modes[(modes.indexOf(motionPreference) + 1) % modes.length];
  try {
    localStorage.setItem("mica-motion-preference", motionPreference);
  } catch {}
  applyMotionPreference();
  toast(
    `Motion set to ${{ auto: "device preference", reduce: "reduced", full: "full" }[motionPreference]}`,
  );
}

function targetAlertStorageKey() {
  return `mica-target-alert-hits-${state.session?.user?.id || "guest"}`;
}

function localActionSnapshot() {
  const positions = state.items.map((item) => ({
    ...item,
    priceObservedAt: item.pricingUpdatedAt,
    priceMovement: item.movement
      ? {
          percent: item.movement.changePercent,
          status: item.pricingStatus === "live" ? "live" : item.pricingStatus,
          observedAt: item.movement.toDate,
          previousObservedAt: item.movement.fromDate,
          source: item.movement.provider || item.referenceProvider,
        }
      : null,
    comparableMovement: item.comparableMovement || null,
  }));
  const gradingSubmissions = state.items.flatMap((item) =>
    (item.gradingSubmissions || []).map((submission) => ({
      ...submission,
      observedAt: submission.statusUpdatedAt,
      source: "saved grading submission",
    })),
  );
  const listings = state.items
    .filter((item) => item.status === "listed")
    .map((item) => ({
      id: item.uid,
      name: item.name,
      updatedAt: item.priceReviewedAt || item.listedAt || item.updatedAt,
      lastReviewedAt: item.priceReviewedAt || item.listedAt,
      reviewReasons: [
        item.askingPrice == null ? "asking price missing" : "",
        item.listingVenue ? "" : "listing venue missing",
        item.listedAt ? "" : "listing date missing",
      ].filter(Boolean),
    }));
  return evaluateActionRules({
    now: new Date().toISOString(),
    thresholds:
      state.actionCenter.preferences.thresholds || DEFAULT_ACTION_THRESHOLDS,
    positions,
    watchlist: state.watchlist,
    goals: state.organization.goals.map((goal) => ({
      ...goal,
      lastProgress: goal.progress,
    })),
    gradingSubmissions,
    listings,
  });
}

async function refreshActionCenter({ persist = true } = {}) {
  if (!state.session?.user?.id) return;
  const ownerId = state.session.user.id;
  const loadVersion = sessionLoadVersion;
  const snapshot = localActionSnapshot();
  if (state.actionCenter.status !== "ready" || !persist) {
    state.actionCenter.items = snapshot;
    if (state.actionCenter.status !== "ready")
      state.actionCenter.status = "local";
    renderBusinessReview();
    updateTargetAlertControl();
    return;
  }
  try {
    await upsertActionCenterSnapshot(supabase, snapshot);
    const durable = await loadActionCenter(supabase, ownerId);
    if (!accountRequestIsCurrent(ownerId, loadVersion)) return;
    state.actionCenter = {
      ...state.actionCenter,
      status: "ready",
      items: durable.items,
      preferences: durable.preferences,
    };
  } catch {
    if (!accountRequestIsCurrent(ownerId, loadVersion)) return;
    state.actionCenter = {
      ...state.actionCenter,
      status: "local",
      items: snapshot,
    };
  }
  renderBusinessReview();
  updateTargetAlertControl();
}

function updateTargetAlertControl() {
  const button = $("#targetAlertButton");
  if (!button) return;
  if (state.actionCenter.status === "ready") {
    const preferences = state.actionCenter.preferences;
    button.disabled = false;
    $("#targetAlertState").textContent = preferences.enabled
      ? preferences.channels.inApp
        ? "On"
        : "Paused"
      : "Paused";
    $("#targetAlertHelp").textContent =
      `${preferences.dailyCap} per channel each day · quiet ${preferences.quietHours.start}–${preferences.quietHours.end} ${preferences.timeZone}`;
    return;
  }
  const supported = "Notification" in window;
  const permission = supported ? Notification.permission : "unsupported";
  if (!supported) {
    button.disabled = true;
    $("#targetAlertState").textContent = "Unavailable";
    $("#targetAlertHelp").textContent =
      "This browser does not support notifications";
    return;
  }
  button.disabled = false;
  if (permission === "denied") {
    targetAlertsEnabled = false;
    try {
      localStorage.setItem("mica-target-alerts", "off");
    } catch {}
    $("#targetAlertState").textContent = "Blocked";
    $("#targetAlertHelp").textContent =
      "Allow notifications in browser settings to use target alerts";
    return;
  }
  $("#targetAlertState").textContent =
    targetAlertsEnabled && permission === "granted" ? "On" : "Off";
  $("#targetAlertHelp").textContent =
    targetAlertsEnabled && permission === "granted"
      ? "Alerts once when a matching price crosses each target"
      : "Alert while Mica is open and prices refresh";
}

async function notifyReachedTargets() {
  if (state.actionCenter.status === "ready") return;
  if (
    !targetAlertsEnabled ||
    !("Notification" in window) ||
    Notification.permission !== "granted"
  )
    return;
  let previous = {};
  try {
    previous = JSON.parse(
      localStorage.getItem(targetAlertStorageKey()) || "{}",
    );
  } catch {}
  const { notifications, next } = targetAlertChanges(state.watchlist, previous);
  try {
    localStorage.setItem(targetAlertStorageKey(), JSON.stringify(next));
  } catch {}
  for (const item of notifications) {
    const evidence = itemWithPriceEvidence(item);
    const source = evidence.referenceProvider
      ? `${evidence.referenceProvider}${evidence.referenceObservedAt ? ` observed ${String(evidence.referenceObservedAt).slice(0, 10)}` : "; observation date unavailable"}`
      : "source unavailable";
    const options = {
      body: `${item.name} is ${money(item.currentPrice, item.currency)} · your target is ${money(item.targetPrice, item.currency)} · ${source}`,
      icon: "./icons/icon-192.png",
      badge: "./icons/icon-192.png",
      tag: `mica-target-${item.watchlistId || item.id}`,
      data: { url: location.origin },
    };
    try {
      const registration = await navigator.serviceWorker?.getRegistration?.();
      if (registration?.showNotification)
        await registration.showNotification("Mica buy target reached", options);
      else new Notification("Mica buy target reached", options);
    } catch {}
  }
}

async function toggleTargetAlerts() {
  if (state.actionCenter.status === "ready") {
    openNotificationPreferencesSheet();
    return;
  }
  if (!("Notification" in window)) return;
  if (targetAlertsEnabled && Notification.permission === "granted") {
    targetAlertsEnabled = false;
    try {
      localStorage.setItem("mica-target-alerts", "off");
      localStorage.removeItem(targetAlertStorageKey());
    } catch {}
    updateTargetAlertControl();
    toast("Buy target alerts turned off");
    return;
  }
  let permission = Notification.permission;
  if (permission === "default")
    permission = await Notification.requestPermission();
  if (permission !== "granted") {
    targetAlertsEnabled = false;
    try {
      localStorage.setItem("mica-target-alerts", "off");
    } catch {}
    updateTargetAlertControl();
    toast("Notifications are blocked in this browser");
    return;
  }
  targetAlertsEnabled = true;
  try {
    localStorage.setItem("mica-target-alerts", "on");
    localStorage.removeItem(targetAlertStorageKey());
  } catch {}
  updateTargetAlertControl();
  toast("Buy target alerts turned on");
  void notifyReachedTargets();
}

function notificationKindLabel(kind) {
  return {
    watch_target: "Buy targets",
    price_change: "Price changes",
    comparable_change: "Comparable sales",
    coverage_loss: "Pricing coverage",
    stale_data: "Stale data",
    collection_goal: "Collection goals",
    grading_opportunity: "Grading opportunities",
    grading_status: "Grading status",
    listing_review: "Listing reviews",
    inventory_aging: "Inventory age",
  }[kind];
}

let devicePushBusy = 0;
async function clearAccountDevicePush(owner, removeRemote = false) {
  devicePushBusy += 1;
  try {
    await disableDevicePush({
      remove:
        removeRemote && owner
          ? (endpoint) => removeWebPushSubscription(supabase, owner, endpoint)
          : undefined,
    });
  } finally {
    devicePushBusy -= 1;
  }
}

function openNotificationPreferencesSheet() {
  if (state.actionCenter.status !== "ready") return;
  const owner = state.session?.user?.id;
  const version = sessionLoadVersion;
  if (!owner) return;
  const preferences = state.actionCenter.preferences;
  const capabilities = state.actionCenter.capabilities;
  const emailAvailable = capabilities.email === "configured_unverified";
  const pushAvailable = capabilities.webPush === "configured_unverified";
  const kindControls = actionRuleKinds()
    .map(
      (kind) =>
        `<label class="notification-kind"><input type="checkbox" name="mutedKind" value="${kind}" ${preferences.mutedKinds.includes(kind) ? "" : "checked"}><span>${esc(notificationKindLabel(kind))}</span></label>`,
    )
    .join("");
  openSheet(
    `<div class="sheet-heading"><div><h2 id="sheetTitle">Action alerts</h2><p>Choose where and when Mica notifies you.</p></div><button class="sheet-close" aria-label="Close">×</button></div><form id="notificationPreferencesForm"><div class="settings-form"><label class="toggle-field"><input type="checkbox" name="enabled" ${preferences.enabled ? "checked" : ""}><span><strong>Enable alerts</strong><small>Pause new alerts anytime.</small></span></label><label class="toggle-field"><input type="checkbox" name="inApp" ${preferences.channels.inApp ? "checked" : ""}><span><strong>In Mica</strong><small>See alerts when you open Mica.</small></span></label><label class="toggle-field"><input type="checkbox" name="email" ${preferences.channels.email ? "checked" : ""} ${!emailAvailable && !preferences.channels.email ? "disabled" : ""}><span><strong>Email</strong><small>${emailAvailable ? "Delivery hasn’t been verified yet." : "Email alerts aren’t available yet."}</small></span></label><label class="toggle-field"><input type="checkbox" name="webPush" ${preferences.channels.webPush ? "checked" : ""} ${!pushAvailable && !preferences.channels.webPush ? "disabled" : ""}><span><strong>Web push</strong><small>${pushAvailable ? "This device needs notification permission." : "Push notifications aren’t available yet."}</small></span></label><section class="device-notification-settings"><strong>This device</strong><p id="devicePushStatus" role="status">Checking notification support…</p><button id="enableDevicePush" class="secondary" type="button" ${pushAvailable ? "" : "disabled"}>Enable on this device</button><button id="disableDevicePush" class="secondary" type="button">Disable on this device</button><small>Device permission is separate from your account’s Web push setting.</small></section><label class="toggle-field"><input type="checkbox" name="quietEnabled" ${preferences.quietHours.enabled ? "checked" : ""}><span><strong>Quiet hours</strong><small>Pause email and push during these hours.</small></span></label><div class="form-grid"><div class="field"><label for="quietStart">Start</label><input id="quietStart" name="quietStart" type="time" value="${esc(preferences.quietHours.start)}"></div><div class="field"><label for="quietEnd">End</label><input id="quietEnd" name="quietEnd" type="time" value="${esc(preferences.quietHours.end)}"></div><div class="field full"><label for="dailyAlertCap">Maximum per channel each day</label><input id="dailyAlertCap" name="dailyCap" type="number" min="1" max="50" step="1" value="${preferences.dailyCap}"></div><div class="field full"><label for="notificationTimeZone">Timezone</label><input id="notificationTimeZone" name="timeZone" value="${esc(preferences.timeZone)}" placeholder="America/Chicago" required><small>Quiet hours and the daily limit use this timezone.</small></div></div><fieldset class="notification-kinds"><legend>Actions to include</legend>${kindControls}</fieldset></div><p class="form-error" id="notificationPreferencesError" role="alert"></p><div class="sheet-actions"><button class="secondary" id="disableOptionalAlerts" type="button">Unsubscribe optional channels</button><button class="primary" type="submit">Save alert settings</button></div></form>`,
  );
  const form = $("#notificationPreferencesForm");
  const errorNode = $("#notificationPreferencesError");
  const current = () =>
    form.isConnected &&
    state.session?.user?.id === owner &&
    sessionLoadVersion === version;
  let saving = false;
  const setSaving = (value) => {
    saving = value;
    form.querySelector('[type="submit"]').disabled = value;
    $("#disableOptionalAlerts").disabled = value;
  };
  const deviceStatus = $("#devicePushStatus");
  const enable = $("#enableDevicePush");
  const disable = $("#disableDevicePush");
  const showDeviceStatus = async () => {
    try {
      const result = await devicePushStatus(owner);
      if (!current()) return;
      deviceStatus.textContent = {
        enabled: "Enabled on this device.",
        disabled: "Not enabled on this device.",
        blocked:
          "Blocked in device settings. Allow notifications there to enable them.",
        unsupported:
          "Not supported here. On iPhone, open Mica from the Home Screen.",
      }[result];
      enable.disabled = !pushAvailable || result === "unsupported";
      disable.disabled = result === "unsupported";
    } catch {
      if (current())
        deviceStatus.textContent =
          "Couldn’t check this device. Retry Enable or Disable.";
    }
  };
  void showDeviceStatus();
  const changeDevice = async (enabled) => {
    if (!current() || devicePushBusy) return;
    devicePushBusy += 1;
    enable.disabled = true;
    disable.disabled = true;
    deviceStatus.textContent = enabled
      ? "Enabling this device…"
      : "Disabling this device…";
    try {
      const remove = (endpoint) =>
        removeWebPushSubscription(supabase, owner, endpoint);
      if (enabled)
        await enableDevicePush({
          ownerId: owner,
          publicKey: capabilities.webPushPublicKey,
          isCurrent: current,
          save: (subscription) =>
            saveWebPushSubscription(supabase, owner, subscription),
          remove,
        });
      else await disableDevicePush({ remove });
      if (current())
        deviceStatus.textContent = enabled
          ? "Enabled on this device. Save Web push above to receive account alerts."
          : "Disabled on this device.";
    } catch (error) {
      if (current())
        deviceStatus.textContent =
          error.message?.includes("permission") ||
          error.message?.includes("blocked") ||
          error.message?.includes("supported")
            ? error.message
            : "Couldn’t update this device. Please retry.";
    } finally {
      devicePushBusy -= 1;
      if (current()) {
        enable.disabled = !pushAvailable;
        disable.disabled = false;
      }
    }
  };
  enable.addEventListener("click", () => changeDevice(true));
  disable.addEventListener("click", () => changeDevice(false));
  $("#disableOptionalAlerts").addEventListener("click", async () => {
    if (!current() || saving) return;
    setSaving(true);
    errorNode.textContent = "";
    try {
      const result = await saveActionCenterPreferences(supabase, {
        ...preferences,
        channels: { ...preferences.channels, email: false, webPush: false },
      });
      if (!current()) return;
      state.actionCenter.preferences = result;
      closeSheet({ discardHistory: true });
      updateTargetAlertControl();
      toast("Optional email and push alerts unsubscribed");
    } catch {
      if (current())
        errorNode.textContent =
          "Couldn’t update alert settings. Please try again.";
    } finally {
      if (current()) setSaving(false);
    }
  });
  form.addEventListener("submit", async (event) => {
    event.preventDefault();
    if (!current() || saving) return;
    const data = new FormData(form);
    let timeZone;
    try {
      timeZone = notificationTimeZone(data.get("timeZone"));
    } catch (error) {
      errorNode.textContent = error.message;
      return;
    }
    const next = normalizeNotificationPreferences({
      enabled: data.get("enabled") === "on",
      channels: {
        inApp: data.get("inApp") === "on",
        email: data.get("email") === "on",
        webPush: data.get("webPush") === "on",
      },
      quietHours: {
        enabled: data.get("quietEnabled") === "on",
        start: data.get("quietStart"),
        end: data.get("quietEnd"),
      },
      timeZone,
      dailyCap: data.get("dailyCap"),
      cooldownHours: preferences.cooldownHours,
      mutedKinds: actionRuleKinds().filter(
        (kind) => !data.getAll("mutedKind").includes(kind),
      ),
    });
    setSaving(true);
    errorNode.textContent = "";
    try {
      const result = await saveActionCenterPreferences(supabase, {
        ...next,
        thresholds: preferences.thresholds,
      });
      if (!current()) return;
      state.actionCenter.preferences = result;
      closeSheet({ discardHistory: true });
      updateTargetAlertControl();
      void refreshActionCenter();
      toast("Alert settings saved");
    } catch {
      if (current())
        errorNode.textContent =
          "Couldn’t save alert settings. Your choices are still here—please try again.";
    } finally {
      if (current()) setSaving(false);
    }
  });
}

async function openInstallExperience() {
  if (isInstalledApp()) {
    toast("Mica is already installed");
    return;
  }
  if (deferredInstallPrompt) {
    const prompt = deferredInstallPrompt;
    deferredInstallPrompt = null;
    await prompt.prompt();
    const choice = await prompt.userChoice;
    updateInstallControl();
    toast(
      choice.outcome === "accepted"
        ? "Mica installation started"
        : "Installation canceled",
    );
    return;
  }
  const ios = /iPad|iPhone|iPod/.test(navigator.userAgent);
  const steps = ios
    ? "<ol><li>Open Mica in Safari.</li><li>Tap the Share button.</li><li>Choose Add to Home Screen, then confirm.</li></ol>"
    : "<ol><li>Open your browser menu.</li><li>Choose Install Mica, Install app, or Add to Home Screen when available.</li><li>Confirm the browser prompt.</li></ol>";
  openSheet(
    `<div class="sheet-heading"><div><h2 id="sheetTitle">Install Mica</h2><p>Keep your collection one tap away.</p></div><button class="sheet-close" aria-label="Close">×</button></div><div class="info-copy">${steps}<p>Once installed, Mica can open without an internet connection. Current prices and saved changes still need internet access.</p></div><div class="sheet-actions"><button class="primary" id="installStepsDone" type="button">Got it</button></div>`,
  );
  $("#installStepsDone").addEventListener("click", closeSheet);
}

function openAccountDeletionSheet() {
  const email = state.session?.user?.email || "";
  openSheet(
    `<div class="sheet-heading"><div><h2 id="sheetTitle">Permanently delete account?</h2><p>This cannot be undone.</p></div><button class="sheet-close" aria-label="Close">×</button></div><div class="warning-panel"><strong>Your account and saved collection will be permanently removed.</strong><p>Type your account email to confirm. You can cancel without changing anything.</p></div><form id="deleteAccountForm"><div class="field"><label for="deleteAccountEmail">Type ${esc(email)}</label><input id="deleteAccountEmail" type="email" autocomplete="off" autocapitalize="none" spellcheck="false" required></div><p class="form-error" id="deleteAccountError" role="alert"></p><div class="sheet-actions"><button class="secondary" id="cancelAccountDeletion" type="button">Keep my account</button><button class="danger-action" id="confirmAccountDeletion" type="submit" disabled>Delete permanently</button></div></form>`,
  );
  const input = $("#deleteAccountEmail");
  const confirm = $("#confirmAccountDeletion");
  input.addEventListener("input", () => {
    confirm.disabled = input.value.trim().toLowerCase() !== email.toLowerCase();
  });
  $("#cancelAccountDeletion").addEventListener("click", closeSheet);
  $("#deleteAccountForm").addEventListener("submit", async (event) => {
    event.preventDefault();
    if (input.value.trim().toLowerCase() !== email.toLowerCase()) return;
    confirm.disabled = true;
    input.disabled = true;
    $("#cancelAccountDeletion").disabled = true;
    $(".sheet-close").disabled = true;
    $("#deleteAccountError").textContent =
      "Deleting your account and saved collection…";
    let accountDeleted = false;
    try {
      const response = await fetch("/api/account", {
        method: "DELETE",
        headers: {
          Authorization: `Bearer ${state.session.access_token}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ confirmation: input.value.trim() }),
      });
      const result = await response.json().catch(() => ({}));
      if (!response.ok)
        throw new Error(
          result.error || `Request failed with status ${response.status}`,
        );
      accountDeleted = true;
      const deletedOwner = state.session?.user?.id;
      await clearAccountDevicePush(deletedOwner).catch(() => {});
      try { await clearDeletedAccountClientData(deletedOwner); }
      finally { await signOut(supabase); }
      location.reload();
    } catch (error) {
      if (accountDeleted) {
        await applySession(null);
        authMessage("Account deleted. Restart Mica to finish local cleanup.", true);
        return;
      }
      confirm.disabled = false;
      input.disabled = false;
      $("#cancelAccountDeletion").disabled = false;
      $(".sheet-close").disabled = false;
      $("#deleteAccountError").textContent =
        `Account was not deleted: ${error.message || "Unknown error"}`;
    }
  });
}

async function clearDeletedAccountClientData(ownerId) {
  const owner = String(ownerId || "");
  if (nativeBuild && owner) {
    const cleanup = await Promise.allSettled([
      nativeRuntime().clearDraft(owner), nativeRuntime().clearDraft(owner, "position-draft"),
    ]);
    if (cleanup.some((result) => result.status === "rejected"))
      throw new Error("Interrupted-work cleanup could not finish.");
  }
  if (owner) {
    try {
      for (let index = localStorage.length - 1; index >= 0; index -= 1) {
        const key = localStorage.key(index) || "";
        if (
          key === `mica-collection-view-${owner}` ||
          key === `mica-target-alert-hits-${owner}` ||
          key === `mica-grading-coach-${owner}-v1` ||
          key.startsWith(`mica-workflow-${owner}-`)
        )
          localStorage.removeItem(key);
      }
    } catch {}
  }
  state.gradingActivityPreviews.clear();
  state.gradingCaptureDrafts.clear();
  if ("caches" in globalThis) {
    try {
      const keys = await caches.keys();
      await Promise.all(
        keys
          .filter((key) => key.startsWith("mica-runtime-"))
          .map((key) => caches.delete(key)),
      );
    } catch {}
  }
}

function downloadTextFile(content, type, filename) {
  const blob = new Blob([content], { type });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = filename;
  link.click();
  setTimeout(() => URL.revokeObjectURL(url), 0);
}

function accountDataUnavailable() {
  return state.accountLoading || Boolean(state.accountLoadError);
}
function requireAccountData() {
  if (!accountDataUnavailable()) return true;
  toast("Reconnect to your cloud library before using this feature");
  return false;
}

function downloadCollectionCsv() {
  if (!requireAccountData()) return false;
  const date = localIsoDate();
  downloadTextFile(
    collectionToCsv(state.items.map(itemWithPriceEvidence)),
    "text/csv;charset=utf-8",
    `mica-collection-${date}.csv`,
  );
  toast("Importable collection CSV downloaded");
  return true;
}

function downloadAccountBackup() {
  if (!requireAccountData()) return false;
  const exportedAt = new Date().toISOString();
  const date = exportedAt.slice(0, 10);
  const content = accountBackupJson({
    items: state.items.map(itemWithPriceEvidence),
    watchlist: state.watchlist.map(itemWithPriceEvidence),
    accountEmail: state.session?.user?.email || "",
    exportedAt,
  });
  downloadTextFile(
    content,
    "application/json;charset=utf-8",
    `mica-account-backup-${date}.json`,
  );
  toast("Complete account backup downloaded");
  return true;
}

function openInsuranceReport() {
  if (!requireAccountData()) return;
  const date = localIsoDate();
  const totals = calculateTotals(state.items, { currency: "USD" });
  const documentation = insuranceDocumentation(state.items);
  const rows = [...state.items]
    .sort((a, b) => (itemValue(b) ?? -1) - (itemValue(a) ?? -1))
    .map((item) => {
      const context = item.gradingCompany
        ? `${item.gradingCompany} grade ${item.grade}`
        : item.condition
          ? conditionLabel(item.condition)
          : "Ungraded · wear not added";
      const basis =
        item.costBasis === null || item.costBasis === undefined
          ? null
          : Number(item.costBasis);
      const value = itemValue(item);
      return `<article class="insurance-row"><img src="${esc(item.thumb || item.image || "./icons/icon.svg")}" alt="${esc(item.name)} reference image"><div class="insurance-card-main"><strong>${esc(item.name)}</strong><span>${esc(item.set)} · ${esc(item.number)} · ${esc(item.variant || "Version unknown")}</span><small>${esc(context)} · ${Number(item.quantity) || 0} owned</small><small class="price-provenance">${esc(priceProvenanceText(item))}</small>${item.certificationNumber ? `<small>Certification number ${esc(item.certificationNumber)}</small>` : ""}${item.location ? `<small>Stored at ${esc(item.location)}</small>` : ""}${item.notes ? `<p>${esc(item.notes)}</p>` : ""}</div><div class="insurance-values"><span>What you paid<strong>${basis === null ? "Not recorded" : money(basis, item.currency)}</strong></span><span>Estimated value today<strong>${value === null ? "Unavailable" : money(value, item.currency)}</strong></span></div></article>`;
    })
    .join("");
  openSheet(
    `<div class="insurance-report"><div class="sheet-heading"><div><h2 id="sheetTitle">Insurance collection report</h2><p>Private account record · ${date}</p></div><button class="sheet-close" aria-label="Close">×</button></div><div class="insurance-owner"><span>Prepared for</span><strong>${esc(profileDisplayName() || "Mica account holder")}</strong><small>${documentation.cards} card${documentation.cards === 1 ? "" : "s"} in ${documentation.positions} saved entr${documentation.positions === 1 ? "y" : "ies"}</small></div><div class="insurance-summary"><div><span>Estimated value today</span><strong>${money(totals.value)}</strong><small>${totals.unpriced ? `${totals.unpriced} card${totals.unpriced === 1 ? "" : "s"} left out because no matching price was found` : "Every card has a matching price"}</small></div><div><span>Total amount recorded as paid</span><strong>${totals.costKnown ? money(totals.cost) : "Unavailable"}</strong><small>${totals.unknownCost ? `${totals.unknownCost} card${totals.unknownCost === 1 ? " is" : "s are"} missing the amount paid` : "Amount paid recorded for every card"}</small></div></div><div class="insurance-documentation"><strong>Details to complete</strong><span>${documentation.missingLocation} saved entr${documentation.missingLocation === 1 ? "y" : "ies"} missing a storage location · ${documentation.missingCertification} graded entr${documentation.missingCertification === 1 ? "y" : "ies"} missing a certification number · ${documentation.missingPrice} missing a current price</span></div><div class="insurance-list">${rows || '<div class="find-empty"><strong>No cards to report</strong><span>Add a card to your library before creating an insurance report.</span></div>'}</div><p class="insurance-disclaimer">Card images help identify the card but do not prove ownership, authenticity, condition, or possession. Prices are estimates, not official appraisals. Add your own photos, receipts, and professional valuations if your insurer asks for them.</p><div class="sheet-actions insurance-actions"><button class="secondary" id="insuranceClose" type="button">Close</button><button class="primary" id="printInsuranceReport" type="button" ${state.items.length ? "" : "disabled"}>Print / Save PDF</button></div></div>`,
  );
  $("#insuranceClose").addEventListener("click", closeSheet);
  $("#printInsuranceReport").addEventListener("click", () => window.print());
}

function openSharePortfolioSheet() {
  if (!requireAccountData()) return;
  openSheet(
    `<div class="sheet-heading"><div><h2 id="sheetTitle">Share a collection summary</h2><p>Preview exactly what will be shared.</p></div><button class="sheet-close" aria-label="Close">×</button></div><label class="share-performance"><input id="sharePerformance" type="checkbox"> Include what I paid and the known change in value</label><pre class="share-preview" id="sharePreview"></pre><div class="simple-note"><strong>Private by default.</strong><br>Notes, storage locations, certification numbers, purchase dates, account details, and buying or selling history are never included.</div><div class="sheet-actions"><button class="secondary" id="copyPortfolioSnapshot" type="button">Copy summary</button>${navigator.share ? '<button class="primary" id="nativeSharePortfolio" type="button">Share…</button>' : ""}</div>`,
  );
  const text = () =>
    portfolioSnapshot(state.items.map(itemWithPriceEvidence), {
      includePerformance: $("#sharePerformance").checked,
    });
  const update = () => {
    $("#sharePreview").textContent = text();
  };
  const copy = async () => {
    try {
      await navigator.clipboard.writeText(text());
      toast("Collection summary copied");
    } catch {
      toast("Copy is unavailable in this browser");
    }
  };
  $("#sharePerformance").addEventListener("change", update);
  $("#copyPortfolioSnapshot").addEventListener("click", copy);
  $("#nativeSharePortfolio")?.addEventListener("click", async () => {
    const button = $("#nativeSharePortfolio");
    button.disabled = true;
    try {
      await navigator.share({
        title: "My Mica Pokémon collection",
        text: text(),
      });
      toast("Collection summary shared");
    } catch (error) {
      if (error?.name !== "AbortError")
        toast("Sharing is unavailable right now");
    } finally {
      button.disabled = false;
    }
  });
  update();
}

async function openImportHistorySheet() {
  if (!requireAccountData()) return;
  openSheet(
    '<div class="sheet-heading"><div><h2 id="sheetTitle">Spreadsheet import history</h2><p>Your recent imports</p></div><button class="sheet-close" aria-label="Close">×</button></div><div class="searching-cards"><i></i><span>Loading recent imports…</span></div>',
  );
  try {
    const jobs = await loadRecentCollectionImports(supabase, 10);
    const rows = jobs
      .map((job) => {
        const totals = job.totals || {};
        const created = Number(totals.createdRows || 0);
        const reused = Number(totals.reusedRows || 0);
        const status = String(job.status || "unknown").replaceAll("_", " ");
        const date = new Date(
          job.committed_at || job.rolled_back_at || job.created_at,
        );
        const dateLabel = Number.isNaN(date.getTime())
          ? "Date unavailable"
          : date.toLocaleString();
        const rollback =
          job.status === "committed"
            ? `<div class="import-history-rollback"><label><input type="checkbox" data-import-rollback-confirm="${esc(job.id)}"> Remove entries added by this import only if they have not changed.</label><button class="danger-action" type="button" data-import-rollback="${esc(job.id)}" disabled>Undo this import</button><p role="status" data-import-rollback-status="${esc(job.id)}"></p></div>`
            : "";
        return `<article class="import-history-row"><div><strong>${esc(job.source_name || "Collection CSV")}</strong><span>${esc(dateLabel)} · ${esc(status)}</span></div><p>${created.toLocaleString()} created · ${reused.toLocaleString()} already saved</p>${rollback}</article>`;
      })
      .join("");
    openSheet(
      `<div class="sheet-heading"><div><h2 id="sheetTitle">Spreadsheet import history</h2><p>Your recent imports</p></div><button class="sheet-close" aria-label="Close">×</button></div>${rows ? `<div class="import-history-list">${rows}</div>` : '<div class="empty-state"><strong>No completed imports yet</strong><p>Your imported spreadsheets will appear here.</p></div>'}`,
    );
    $$("[data-import-rollback-confirm]").forEach((control) =>
      control.addEventListener("change", () => {
        const button = $(
          `[data-import-rollback="${control.dataset.importRollbackConfirm}"]`,
        );
        if (button) button.disabled = !control.checked;
      }),
    );
    $$("[data-import-rollback]").forEach((button) =>
      button.addEventListener("click", async () => {
        const jobId = button.dataset.importRollback;
        const status = $(`[data-import-rollback-status="${jobId}"]`);
        button.disabled = true;
        status.textContent = "Checking imported entries…";
        try {
          const result = await rollbackCollectionImport(supabase, jobId);
          await reloadPortfolio();
          toast(
            `${Number(result.removedRows || 0).toLocaleString()} untouched imported entries removed`,
          );
          await openImportHistorySheet();
        } catch (error) {
          button.disabled = false;
          status.textContent =
            "Could not confirm the undo. Check import history before trying again.";
        }
      }),
    );
  } catch (error) {
    openSheet(
      `<div class="sheet-heading"><div><h2 id="sheetTitle">Spreadsheet import history</h2><p>Your recent imports</p></div><button class="sheet-close" aria-label="Close">×</button></div><div class="unavailable-panel"><strong>Import history is unavailable.</strong><br>Close this window and try again.</div>`,
    );
  }
}

function handleCsv(file) {
  if (!requireAccountData()) return;
  const reader = new FileReader();
  reader.onerror = () => toast("Mica could not read that CSV");
  reader.onload = () => void openCsvImportReview(String(reader.result), file);
  reader.readAsText(file);
}

export async function openCsvImportReview(csvText, file) {
  const ingestionSessionId = crypto.randomUUID();
  const ingestionStartedAt = performance.now();
  const inspection = inspectCollectionCsv(csvText);
  if (!inspection.rowCount || inspection.errors.length) {
    toast(inspection.errors[0] || "No importable rows found");
    return;
  }
  let mapping = { ...inspection.suggestedMapping };
  try {
    const saved = await loadImportMappingProfile(
      supabase,
      inspection.headerSignature,
    );
    if (saved?.mapping) mapping = { ...mapping, ...saved.mapping };
  } catch {}
  const today = localIsoDate();
  const headerOptions = inspection.headers
    .map(
      (header, index) =>
        `<option value="${esc(inspection.normalizedHeaders[index])}">${esc(header)}</option>`,
    )
    .join("");
  const mappingFields = COLLECTION_IMPORT_FIELDS.map(
    (field) =>
      `<label class="import-mapping-row" for="importMap-${esc(field.key)}"><span>${esc(field.label)}${field.required ? " *" : ""}</span><select id="importMap-${esc(field.key)}" data-import-map="${esc(field.key)}" ${field.required ? "required" : ""}><option value="">${field.required ? "Choose a column" : "Not included"}</option>${headerOptions}</select></label>`,
  ).join("");
  openSheet(
    `<div class="sheet-heading"><div><h2 id="sheetTitle">Review spreadsheet import</h2><p>${esc(inspection.source)} · ${inspection.totalRowCount.toLocaleString()} data row${inspection.totalRowCount === 1 ? "" : "s"}</p></div><button class="sheet-close" aria-label="Close">×</button></div><div class="import-safety-note"><strong>Nothing enters your library during preview.</strong><span>Check the rows below before adding them to your collection.</span></div><details class="import-mapping"><summary>Match spreadsheet columns</summary><div class="import-mapping-grid">${mappingFields}</div><label class="field-choice"><input id="saveImportMapping" type="checkbox" checked> Remember these column choices</label></details><div class="field"><label for="importFallbackDate">Temporary ordering date when the real purchase date is missing</label><input id="importFallbackDate" type="date" max="${today}" value="${today}" required><small>This date is marked unknown and is never presented as the real purchase date.</small></div><section class="import-dry-run" id="importDryRun" aria-live="polite"><div class="searching-cards"><i></i><span>Preparing row preview…</span></div></section><section class="import-progress" id="importProgress" aria-labelledby="importProgressTitle" hidden><div><strong id="importProgressTitle">Preparing your import…</strong><span id="importProgressCount">0</span></div><progress id="importProgressBar" max="1" value="0">0%</progress><small id="importProgressHelp">Your collection has not changed.</small></section><p class="form-error" id="importStatus" role="status" aria-live="polite"></p><div class="sheet-actions import-actions"><button class="secondary" id="cancelCsvImport" type="button">Cancel</button><button class="secondary" id="runCsvDryCheck" type="button">Check import</button><button class="primary" id="commitCsvImport" type="button" disabled>Import all rows</button></div>`,
  );
  for (const field of COLLECTION_IMPORT_FIELDS) {
    const control = $(`#importMap-${field.key}`);
    if (control) control.value = mapping[field.key] || "";
  }

  let current = null;
  let dryCheckPassed = false;
  let importJobId = null;
  let stagedRows = [];
  let staging = false;
  const setControlsDisabled = (disabled) => {
    $$("[data-import-map],#importFallbackDate,#saveImportMapping").forEach(
      (control) => (control.disabled = disabled),
    );
    $("#cancelCsvImport").disabled = disabled;
    $(".sheet-close").disabled = disabled;
    $("#runCsvDryCheck").disabled = disabled;
  };
  const readMapping = () =>
    Object.fromEntries(
      $$("[data-import-map]").map((control) => [
        control.dataset.importMap,
        control.value,
      ]),
    );
  const prepare = (record, index) => {
    const sourceRows = record.sourceRows || [index + 2];
    const rowLabel =
      sourceRows.length > 1
        ? `Rows ${sourceRows.join(", ")}`
        : `Row ${sourceRows[0]}`;
    const cardState =
      record.cardState === "sealed"
        ? "sealed"
        : record.cardState === "graded" || Boolean(record.gradingCompany)
          ? "graded"
          : "raw";
    const rawCondition =
      cardState === "raw"
        ? normalizeRawCondition(record.rawCondition || record.condition)
            .normalized
        : null;
    const grader =
      cardState === "graded"
        ? normalizeGrader(record.gradingCompany).normalized
        : null;
    const grade = cardState === "graded" ? normalizeGrade(record.grade) : null;
    const acquisitionDateKnown = Boolean(record.purchaseDate);
    const transactionDate =
      record.purchaseDate || $("#importFallbackDate").value;
    const total =
      record.totalAcquisitionCost ??
      (record.cost === null
        ? null
        : Number(record.cost) * Number(record.quantity));
    const acquisitionCostKnown = total !== null;
    if (
      acquisitionCostKnown &&
      (!Number.isFinite(Number(total)) || Number(total) < 0)
    )
      return { error: `${rowLabel}: purchase price is invalid` };
    if (!/^\d{4}-\d{2}-\d{2}$/.test(transactionDate) || transactionDate > today)
      return {
        error: `${rowLabel}: purchase date is invalid or in the future`,
      };
    if (cardState === "graded" && (!grader || !grade))
      return {
        error: `${rowLabel}: graded cards need a supported grader and grade`,
      };
    if (
      String(record.location || "").length > 250 ||
      String(record.notes || "").length > 10000 ||
      String(record.folder || "").length > 100
    )
      return { error: `${rowLabel}: folder, location, or notes are too long` };
    const customFields = normalizeCustomFields(record.customFields);
    if (
      Object.keys(customFields).length !==
      Object.keys(record.customFields || {}).length
    )
      return {
        error: `${rowLabel}: custom fields contain an unsupported key or value`,
      };
    if (
      (record.tags || []).length > 50 ||
      (record.tags || []).some(
        (tag) => !String(tag).trim() || String(tag).trim().length > 40,
      )
    )
      return { error: `${rowLabel}: labels must be 1–40 characters each` };
    const exact =
      cardState === "sealed"
        ? null
        : catalog.find((item) => item.id === record.id) ||
          (record.externalIds?.tcgplayer
            ? catalog.find(
                (item) =>
                  String(item.externalIds?.tcgplayer || "") ===
                  String(record.externalIds.tcgplayer),
              )
            : null) ||
          catalog.find(
            (item) =>
              normalizeIdentity(item.name) === normalizeIdentity(record.name) &&
              normalizeIdentity(item.set) === normalizeIdentity(record.set) &&
              normalizeIdentity(item.number) ===
                normalizeIdentity(record.number),
          );
    const sealedId =
      cardState === "sealed"
        ? String(record.id || "").match(/^sealed:(\d{1,12})$/)?.[1] || null
        : null;
    const card = {
      ...record,
      ...exact,
      id:
        exact?.id ||
        record.id ||
        `import:${normalizeIdentity(`${record.name}-${record.set}-${record.number}`) || "card"}`,
      language: record.language || exact?.language || "en",
      variant:
        record.variant ||
        exact?.variant ||
        (cardState === "sealed" ? "Sealed product" : "Unknown"),
      productType:
        cardState === "sealed"
          ? record.productType || "sealed"
          : record.productType || exact?.productType || null,
      externalIds:
        cardState === "sealed" && sealedId
          ? { pkmnpricesSealed: Number(sealedId) }
          : { ...(exact?.externalIds || {}), ...(record.externalIds || {}) },
    };
    const breakdown = acquisitionFromTotal(
      acquisitionCostKnown ? total : 0,
      record.quantity,
    );
    if (!breakdown)
      return { error: `${rowLabel}: total or quantity is invalid` };
    const currency = /^[A-Z]{3}$/.test(record.currency || "USD")
      ? record.currency
      : "USD";
    const ingestion = confirmIngestionEnvelope(
      createIngestionEnvelope({
        channel: "csv",
        item: card,
        variant: card.variant,
        candidateStatus: exact?.identityStatus || "needs_review",
        source: record.source || inspection.source,
      }),
    );
    return {
      record,
      sourceRows,
      keyRecord: {
        ...record,
        id: card.id,
        language: card.language,
        variant: card.variant,
        cardState,
        rawCondition,
        gradingCompany: grader,
        grade,
        quantity: Number(record.quantity),
        totalAcquisitionCost: acquisitionCostKnown ? Number(total) : null,
        purchaseDate: transactionDate,
        currency,
      },
      payload: {
        ...breakdown,
        identity: {
          ...identitySnapshot(card, card.variant, ingestion),
          acquisitionCostKnown,
          acquisitionDateKnown,
          importSourceRows: sourceRows,
        },
        cardId: exact?.cardId || null,
        variantId:
          exact?.variantId && UUID_PATTERN.test(exact.variantId)
            ? exact.variantId
            : null,
        cardState,
        rawCondition,
        grader,
        grade,
        certificationNumber: record.certificationNumber || null,
        quantity: Number(record.quantity),
        transactionDate,
        currency,
        marketplace: null,
        acquisitionMethod: "unknown",
        notes: record.notes || null,
        folder: record.folder || null,
        location: record.location || null,
        tags: (record.tags || []).slice(0, 50),
        customFields,
      },
    };
  };
  const renderPreview = ({ markDryRun = false } = {}) => {
    mapping = readMapping();
    const parsed = parseCollectionCsv(csvText, { mapping, limit: 5000 });
    const plan = buildCollectionImportPreview(parsed.records, parsed.errors);
    const prepared = plan.rows.map(prepare);
    const preparationErrors = prepared
      .filter((row) => row.error)
      .map((row) => row.error);
    const ready = prepared.filter((row) => !row.error);
    current = {
      parsed,
      plan,
      ready,
      errors: [...plan.errors, ...preparationErrors],
    };
    dryCheckPassed =
      markDryRun && current.errors.length === 0 && ready.length > 0;
    const summary = plan.summary;
    if (markDryRun)
      logIngestionEvent({
        sessionId: ingestionSessionId,
        channel: "csv",
        stage: "previewed",
        outcome: dryCheckPassed ? "success" : "failure",
        durationMs: performance.now() - ingestionStartedAt,
        metadata: {
          rowCount: inspection.totalRowCount,
          stagedCount: ready.length,
          invalidCount: current.errors.length,
          duplicateCount: summary.exactDuplicates,
          reason: dryCheckPassed ? "preview_passed" : "validation_failed",
        },
      });
    const issues = [
      ...current.errors.slice(0, 8),
      ...plan.identityDuplicates
        .slice(0, 4)
        .map(
          (duplicate) =>
            `Rows ${duplicate.matchesRow} and ${duplicate.rowNumber} have the same card identity but different purchase facts; both remain separate.`,
        ),
    ];
    const previewRows = ready
      .slice(0, 12)
      .map(
        ({ record, sourceRows }) =>
          `<tr><td>${esc(sourceRows.join(", "))}</td><td><strong>${esc(record.name)}</strong><small>${esc([record.set, record.number].filter(Boolean).join(" · ") || "Identity details missing")}</small></td><td>${Number(record.quantity).toLocaleString()}</td><td>${esc(record.variant || "Needs review")}</td><td>${esc(record.condition || record.gradingCompany || "Not recorded")}</td></tr>`,
      );
    $("#importDryRun").innerHTML =
      `<div class="import-summary-grid"><div><span>Rows ready</span><strong>${ready.length.toLocaleString()}</strong></div><div><span>Total cards/products</span><strong>${summary.totalQuantity.toLocaleString()}</strong></div><div><span>Exact repeats combined</span><strong>${summary.exactDuplicates.toLocaleString()}</strong></div><div><span>Issues to fix</span><strong>${current.errors.length.toLocaleString()}</strong></div></div>${issues.length ? `<div class="unavailable-panel"><strong>${current.errors.length ? "Fix these before importing" : "Duplicate report"}</strong><br>${issues.map(esc).join("<br>")}</div>` : '<div class="simple-note"><strong>No row errors found.</strong><br>Check the import when you are ready.</div>'}<div class="import-preview-table-wrap"><table class="import-preview-table"><thead><tr><th>CSV row</th><th>Card</th><th>Qty</th><th>Version</th><th>Condition</th></tr></thead><tbody>${previewRows.join("")}</tbody></table></div>${ready.length > 12 ? `<small>Showing 12 of ${ready.length.toLocaleString()} entries.</small>` : ""}`;
    $("#commitCsvImport").disabled = !dryCheckPassed;
    $("#commitCsvImport").textContent = dryCheckPassed
      ? `Import ${ready.length.toLocaleString()} entr${ready.length === 1 ? "y" : "ies"}`
      : "Import all rows";
    $("#importStatus").textContent = dryCheckPassed
      ? "Ready to import. Your library is still unchanged."
      : current.errors.length
        ? "Correct the column choices or spreadsheet, then check again."
        : "Review the rows, then check the import.";
  };
  $$("[data-import-map],#importFallbackDate").forEach((control) =>
    control.addEventListener("change", () => {
      importJobId = null;
      stagedRows = [];
      renderPreview();
    }),
  );
  $("#cancelCsvImport").addEventListener("click", closeSheet);
  $("#runCsvDryCheck").addEventListener("click", () =>
    renderPreview({ markDryRun: true }),
  );
  $("#commitCsvImport").addEventListener("click", async () => {
    if (!dryCheckPassed || !current?.ready.length || staging) return;
    staging = true;
    setControlsDisabled(true);
    $("#commitCsvImport").disabled = true;
    $("#importProgress").hidden = false;
    $("#bottomSheet").dataset.lockClose = "true";
    try {
      if (!stagedRows.length) {
        for (const row of current.ready) {
          const idempotencyKey = await importRecordKey(row.keyRecord);
          stagedRows.push({
            rowNumber: row.sourceRows[0],
            idempotencyKey,
            payload: row.payload,
          });
        }
      }
      if (!importJobId)
        importJobId = await beginCollectionImport(supabase, {
          sourceName: current.parsed.source || inspection.source,
          fileSha256: await sha256Text(csvText),
          headerSignature: inspection.headerSignature,
          mapping,
          preview: current.plan.summary,
        });
      const chunks = chunkImportRows(stagedRows, 200);
      $("#importProgressBar").max = stagedRows.length;
      let staged = 0;
      for (const chunk of chunks) {
        await stageCollectionImportRows(supabase, importJobId, chunk);
        staged += chunk.length;
        $("#importProgressBar").value = staged;
        $("#importProgressCount").textContent =
          `${staged.toLocaleString()} of ${stagedRows.length.toLocaleString()}`;
        $("#importProgressHelp").textContent =
          "Preparing rows · your collection is still unchanged.";
      }
      logIngestionEvent({
        sessionId: ingestionSessionId,
        channel: "csv",
        stage: "staged",
        outcome: "success",
        durationMs: performance.now() - ingestionStartedAt,
        metadata: {
          stagedCount: stagedRows.length,
          retry: Boolean(importJobId),
        },
      });
      const serverPreview = await previewCollectionImport(
        supabase,
        importJobId,
      );
      if (
        Number(serverPreview.invalidRows) !== 0 ||
        Number(serverPreview.validRows) !== stagedRows.length
      )
        throw new Error(
          "The server dry check disagreed with this preview. Nothing was imported.",
        );
      $("#importProgressTitle").textContent = "Saving your import…";
      const result = await commitCollectionImport(supabase, importJobId);
      logIngestionEvent({
        sessionId: ingestionSessionId,
        channel: "csv",
        stage: "committed",
        outcome: "success",
        durationMs: performance.now() - ingestionStartedAt,
        metadata: {
          rowCount: inspection.totalRowCount,
          stagedCount: stagedRows.length,
          duplicateCount: current.plan.summary.exactDuplicates,
        },
      });
      if ($("#saveImportMapping").checked)
        try {
          await saveImportMappingProfile(supabase, {
            sourceName: current.parsed.source || inspection.source,
            headerSignature: inspection.headerSignature,
            mapping,
          });
        } catch {}
      await reloadPortfolio();
      $("#bottomSheet").dataset.lockClose = "false";
      openSheet(
        `<div class="sheet-heading"><div><h2 id="sheetTitle">Import complete</h2><p>Your collection has been updated</p></div><button class="sheet-close" aria-label="Close">×</button></div><div class="import-complete"><span aria-hidden="true">✓</span><strong>${Number(result.createdRows || 0).toLocaleString()} new entr${Number(result.createdRows || 0) === 1 ? "y" : "ies"} saved</strong><p>${Number(result.reusedRows || 0).toLocaleString()} already saved. Exact repeats in the spreadsheet were combined.</p></div><div class="warning-panel"><strong>Need to undo this import?</strong><p>Undo removes entries added by this import only if they have not changed. Later purchases, sales, grading, and edits are protected.</p></div><p class="form-error" id="importRollbackStatus" role="status"></p><div class="sheet-actions"><button class="secondary" id="viewImportedCollection" type="button">View collection</button><button class="danger-action" id="rollbackCsvImport" type="button">Undo import</button></div>`,
      );
      $("#viewImportedCollection").addEventListener("click", () => {
        closeSheet({ discardHistory: true });
        routeTo("collection");
      });
      $("#rollbackCsvImport").addEventListener("click", async (event) => {
        const button = event.currentTarget;
        button.disabled = true;
        $("#importRollbackStatus").textContent = "Checking imported entries…";
        try {
          const rolledBack = await rollbackCollectionImport(
            supabase,
            importJobId,
          );
          logIngestionEvent({
            sessionId: ingestionSessionId,
            channel: "csv",
            stage: "rolled_back",
            outcome: "success",
            durationMs: performance.now() - ingestionStartedAt,
            metadata: { rowCount: Number(rolledBack.removedRows || 0) },
          });
          await reloadPortfolio();
          $("#importRollbackStatus").textContent =
            `${Number(rolledBack.removedRows || 0).toLocaleString()} imported entr${Number(rolledBack.removedRows || 0) === 1 ? "y" : "ies"} removed. Reused entries were left unchanged.`;
          button.remove();
          toast("Import undone");
        } catch (error) {
          button.disabled = false;
          $("#importRollbackStatus").textContent =
            "Could not confirm the undo. Check import history before trying again.";
        }
      });
    } catch (error) {
      logIngestionEvent({
        sessionId: ingestionSessionId,
        channel: "csv",
        stage: "failed",
        outcome: "failure",
        durationMs: performance.now() - ingestionStartedAt,
        metadata: {
          rowCount: inspection.totalRowCount,
          stagedCount: stagedRows.length,
          reason: ingestionFailureReason(error),
          offline: !navigator.onLine,
          retry: Boolean(importJobId),
        },
      });
      staging = false;
      $("#bottomSheet").dataset.lockClose = "false";
      setControlsDisabled(false);
      $("#commitCsvImport").disabled = false;
      $("#commitCsvImport").textContent = importJobId
        ? "Retry import"
        : "Try import again";
      $("#importProgressTitle").textContent = "Import needs another try";
      $("#importProgressHelp").textContent =
        "Retry this import to check its result and finish without adding the same rows twice.";
      $("#importStatus").textContent =
        "We could not confirm the import finished. Your column choices are still here. Try again.";
    }
  });
  renderPreview();
}

async function refreshLivePricing(positionIds = null) {
  const owner = state.session?.user?.id;
  const version = sessionLoadVersion;
  if (portfolioPricingRequest?.owner === owner && portfolioPricingRequest.version === version) {
    await portfolioPricingRequest.promise;
    if (!positionIds || !accountRequestIsCurrent(owner, version)) return;
  }
  const request = { owner, version, promise: updateLivePricing(positionIds) };
  portfolioPricingRequest = request;
  try { await request.promise; } finally { if (portfolioPricingRequest === request) portfolioPricingRequest = null; }
}

async function updateLivePricing(positionIds = null) {
  const selectedPositions = positionIds ? new Set(positionIds) : null;
  const ownerId = state.session?.user?.id;
  const loadVersion = sessionLoadVersion;
  if (!ownerId) return;
  const originalItems = state.items;
  let updatedItems = [...originalItems];
  const uniqueItems = originalItems.filter(item => item.id && (!selectedPositions || selectedPositions.has(item.uid)) && !(item.historyStatus === "live" && item.pricingStatus === "live" && Date.now() - Number(item.historyLoadedAt) < 15 * 60_000));
  if (!uniqueItems.length) return;
  const cardItems = [...new Map(uniqueItems.filter(item => item.cardState !== "sealed" && item.cardState !== "graded" && !item.gradingCompany).map(item => [item.id, item])).values()];
  const sealedItems = [...new Map(uniqueItems.filter(item => item.cardState === "sealed").map(item => [item.id, item])).values()];
  const lookups = cardItems.map((item) => ({
    clientId: item.id,
    pkmnpricesId: item.externalIds?.pkmnprices || "",
    justtcgId: item.externalIds?.justtcg || "",
    tcgplayerId: item.externalIds?.tcgplayer || "",
    tcgdexId: item.externalIds?.tcgdex || "",
    name: item.name,
    set: item.set,
    number: item.number,
    language: item.language || "en",
  }));
  const signal = AbortSignal.timeout(60_000);
  state.pricingStatus = "loading";
  renderCollection();
  try {
    const cards = new Map();
    const sealedProducts = new Map();
    const processedIds = new Set();
    const failedIds = new Set();
    const sealedProcessed = new Set();
    let partial = false;
    let rateLimited = false;
    let retrievedAt = null;
    for (let start = 0; start < lookups.length; start += 2) {
      if (!accountRequestIsCurrent(ownerId, loadVersion)) return;
      const batch = lookups.slice(start, start + 2);
      if (signal.aborted) { partial = true; break; }
      let response;
      try { response = await fetch(
        `/api/cards?history=full&lookups=${encodeURIComponent(JSON.stringify(batch))}`,
        { headers: providerRequestHeaders(), signal },
      ); } catch { partial = true; batch.forEach(lookup => failedIds.add(lookup.clientId)); if (signal.aborted) break; continue; }
      if (response.status === 429) {
        rateLimited = true;
        partial = true;
        break;
      }
      if (!response.ok) { partial = true; batch.forEach(lookup => failedIds.add(lookup.clientId)); continue; }
      const payload = await response.json();
      if (!accountRequestIsCurrent(ownerId, loadVersion)) return;
      retrievedAt = payload.retrievedAt || retrievedAt;
      batch.forEach((lookup) => processedIds.add(lookup.clientId));
      (payload.cards || []).forEach((card) =>
        cards.set(card.providerCardId, card),
      );
      partial =
        partial || Boolean(payload.partial) || payload.unavailable?.length > 0;
    }
    for (let start = 0; start < sealedItems.length; start += 1) {
      if (!accountRequestIsCurrent(ownerId, loadVersion)) return;
      if (rateLimited || signal.aborted) { partial = true; break; }
      const batch = sealedItems.slice(start, start + 1);
      const results = await Promise.allSettled(
        batch.map(async (item) => {
          const id =
            item.externalIds?.pkmnpricesSealed ||
            String(item.id).replace(/^sealed:/, "");
          signal.throwIfAborted();
          const response = await fetch(
            `/api/sealed?id=${encodeURIComponent(id)}`,
            { headers: providerRequestHeaders(), signal },
          );
          if (!response.ok) throw new Error(String(response.status));
          const payload = await response.json();
          if (!accountRequestIsCurrent(ownerId, loadVersion)) return null;
          retrievedAt = payload.retrievedAt || retrievedAt;
          return { item, product: payload.product };
        }),
      );
      results.forEach((result, index) => {
        const item = batch[index];
        sealedProcessed.add(item.id);
        if (result.status === "fulfilled" && sealedProductMatches(item, result.value?.product))
          sealedProducts.set(item.id, result.value.product);
        else partial = true;
      });
    }
    function applyPricing(item) {
      if (item.cardState === "graded" || item.gradingCompany) return item;
      const sealed = item.cardState === "sealed";
      const card = sealed ? sealedProducts.get(item.id) : cards.get(item.id);
      const processed = sealed
        ? sealedProcessed.has(item.id)
        : processedIds.has(item.id);
      if (!processed && failedIds.has(item.id)) {
        const pricing = quotePricingFields(selectPositionQuote(item.quotes || [], item), item, item);
        return { ...item, ...pricing, pricingStatus: pricing.price == null ? "error" : pricing.pricingStatus, pricingReason: "provider_refresh_failed" };
      }
      if (!processed)
        return rateLimited && (!selectedPositions || selectedPositions.has(item.uid))
          ? {
              ...item,
              pricingStatus:
                item.price == null ? "rate_limited" : item.pricingStatus,
            }
          : item;
      if (!card) return { ...item, pricingReason: "provider_match_missing", pricingStatus: item.price != null ? item.pricingStatus : "missing" };
      const quote = selectPositionQuote(card.quotes, item);
      if (!selectPositionQuote(card.quotes, item) && selectPositionQuote(item.quotes || [], item)) return { ...item, pricingReason: "provider_refresh_failed" };
      const quoteState = quote ? quoteStatus(quote) : null;
      const capabilityState = capabilityStatusForItem(card, item);
      const updated = {
        ...item,
        image: item.image || normalizeCardImageSource(card.images?.large)?.href || null,
        thumb: item.thumb || normalizeCardImageSource(card.images?.small)?.href || null,
        externalIds: {
          ...(item.externalIds || {}),
          ...(card.externalIds || {}),
        },
        metadata: card.metadata || item.metadata || null,
        productType: card.productType || item.productType || null,
        price: quoteState === "live" ? quote.amount : null,
        referencePrice: quote?.amount ?? null,
        quotes: card.quotes,
        priceCapabilities: card.capabilities || null,
        historyLoadedAt: Date.now(),
        historyLoadedKey: JSON.stringify([ownerId, loadVersion, detailIdentityKey(item), detailContextKey(valuationContextForItem(item))]),
        historyStatus: card.historyStatus === "not_requested" ? item.historyStatus : card.historyStatus || null,
        priceHistory: quote
          ? recordPriceObservation(
              item,
              quote,
              mergePriceHistory(item.priceHistory || [], card.history || []),
            )
          : mergePriceHistory(item.priceHistory || [], card.history || []),
        pricingStatus: quoteState || capabilityState.status,
        pricingReason: quoteState
          ? priceFreshness(quote).reason
          : capabilityState.reason,
        pricingUpdatedAt:
          quote?.observedAt || quote?.retrievedAt?.slice(0, 10) || null,
      };
      const movement = movementForItem(updated);
      return { ...updated, move: movement?.changePercent ?? null, movement };
    }
    if (!accountRequestIsCurrent(ownerId, loadVersion)) return;
    updatedItems = updatedItems.map(applyPricing);

    const gradedGroups = new Map();
    for (const item of updatedItems) {
      if (!(item.cardState === "graded" || item.gradingCompany) || (selectedPositions && !selectedPositions.has(item.uid))) continue;
      const printing = selectedPrinting(item);
      if (printing.status !== "exact" || [printing.finish, printing.edition, printing.promoType].includes("unknown") || item.gradeQualifier == null) {
        item.pricingStatus = "missing"; item.pricingReason = "printing_confirmation_required";
        continue;
      }
      const key = detailIdentityKey(item) + "|" + detailContextKey(valuationContextForItem(item));
      if (uniqueItems.includes(originalItems.find(copy => copy.uid === item.uid)) && !gradedGroups.has(key)) gradedGroups.set(key, item);
    }
    for (const [key, item] of gradedGroups) {
      if (!accountRequestIsCurrent(ownerId, loadVersion)) return;
      try {
        if (signal.aborted) { partial = true; break; }
        const { response, payload } = await fetchSaleEvidence(saleLookupForItem(item), signal);
        if (!accountRequestIsCurrent(ownerId, loadVersion)) return;
        if (!response.ok) { partial = true; if (response.status === 429) break; continue; }
        const evidence = { ...payload, salesStatus: "live", selectionKey: detailIdentityKey(item), contextKey: detailContextKey(valuationContextForItem(item)) };
        const result = exactSoldValuation(evidence.sales || [], exactSaleContext(item, valuationContextForItem(item)), { validatedContext: evidence.validatedContext, retrievedAt: evidence.retrievedAt, hasMore: evidence.hasMore });
        updatedItems = updatedItems.map(copy => detailIdentityKey(copy) + "|" + detailContextKey(valuationContextForItem(copy)) === key ? { ...copy, exactSaleEvidence: evidence, historyLoadedAt: Date.now(), historyStatus: "live", price: result.status === "ready" ? result.estimate : null, referencePrice: result.estimate, pricingStatus: result.status === "ready" ? "live" : result.status === "stale" ? "stale" : "missing", pricingUpdatedAt: result.newestSoldAt } : copy);
      } catch { partial = true; }
    }
    if (!accountRequestIsCurrent(ownerId, loadVersion)) return;
    state.items = state.items.map(item => {
      const original = originalItems.find(copy => copy.uid === item.uid);
      return original === item ? updatedItems.find(copy => copy.uid === item.uid) || item : item;
    });
    const coverage = portfolioPriceCoverage(state.items);
    state.pricingStatus =
      partial || coverage.liveAutomaticUnits < coverage.totalUnits
        ? "partial"
        : "live";
    catalog = catalog.map(item => cards.has(item.id) ? applyPricing(item) : item);
    state.pricingRetrievedAt = retrievedAt;
    renderCollection();
    if (!state.largeInventory.active) await capturePortfolioValuation();
    renderInsights();
    if (state.route === "detail") renderDetail();
    if (state.route === "insights") void refreshMovementHistory();
    if (!state.largeInventory.active) void backfillPurchaseMarketReferences();
  } catch {
    if (!accountRequestIsCurrent(ownerId, loadVersion)) return;
    state.pricingStatus = "error";
    state.items = state.items.map((item) => {
      if (selectedPositions && !selectedPositions.has(item.uid)) return item;
      const quote = selectPositionQuote(item.quotes, item);
      const pricing = quotePricingFields(quote, item, item);
      return {
        ...item,
        ...pricing,
        pricingStatus: quote ? pricing.pricingStatus : "error",
        pricingReason: quote
          ? `${pricing.pricingReason}:refresh_failed`
          : "provider_refresh_failed",
      };
    });
    renderCollection();
    renderInsights();
  }
}

async function refreshMovementHistory() {
  const ownerId = state.session?.user?.id;
  const loadVersion = sessionLoadVersion;
  if (
    !ownerId ||
    !["idle", "error"].includes(state.movementStatus) ||
    !state.items.some((item) => item.cardState !== "sealed")
  )
    return;
  const cardItems = [
    ...new Map(
      state.items
        .filter((item) => item.cardState !== "sealed" && item.id)
        .map((item) => [item.id, item]),
    ).values(),
  ];
  const lookups = cardItems.map((item) => ({
    clientId: item.id,
    pkmnpricesId: item.externalIds?.pkmnprices || "",
    justtcgId: item.externalIds?.justtcg || "",
    tcgplayerId: item.externalIds?.tcgplayer || "",
    tcgdexId: item.externalIds?.tcgdex || "",
    name: item.name,
    set: item.set,
    number: item.number,
    language: item.language || "en",
  }));
  state.movementStatus = "loading";
  renderInsights();
  try {
    const cards = new Map();
    let planLimited = false;
    let failed = false;
    for (let start = 0; start < lookups.length; start += 1) {
      if (!accountRequestIsCurrent(ownerId, loadVersion)) return;
      const batch = lookups.slice(start, start + 1);
      const response = await fetch(
        `/api/cards?history=full&lookups=${encodeURIComponent(JSON.stringify(batch))}`,
        { headers: providerRequestHeaders() },
      );
      if (!response.ok) {
        failed = true;
        if ([401, 403, 429].includes(response.status)) break;
        continue;
      }
      const payload = await response.json();
      if (!accountRequestIsCurrent(ownerId, loadVersion)) return;
      (payload.cards || []).forEach((card) => {
        cards.set(card.providerCardId, card);
        if (card.historyStatus === "plan_required") planLimited = true;
      });
    }
    if (!accountRequestIsCurrent(ownerId, loadVersion)) return;
    state.items = state.items.map((item) => {
      const card = cards.get(item.id);
      if (!card) return item;
      const quote = selectPositionQuote(card.quotes, item);
      const quoteState = quote ? quoteStatus(quote) : null;
      const capabilityState = capabilityStatusForItem(card, item);
      const updated = {
        ...item,
        externalIds: {
          ...(item.externalIds || {}),
          ...(card.externalIds || {}),
        },
        metadata: card.metadata || item.metadata || null,
        priceCapabilities:
          card.capabilities ||
          card.priceCapabilities ||
          item.priceCapabilities ||
          null,
        price: quoteState === "live" ? quote.amount : quote ? null : item.price,
        referencePrice: quote?.amount ?? item.referencePrice ?? null,
        quotes: card.quotes || item.quotes || [],
        historyStatus: card.historyStatus || item.historyStatus || null,
        priceHistory: recordPriceObservation(
          item,
          quote,
          mergePriceHistory(item.priceHistory || [], card.history || []),
        ),
        pricingStatus:
          quoteState || capabilityState.status || item.pricingStatus,
        pricingReason: quoteState
          ? priceFreshness(quote).reason
          : capabilityState.reason,
        pricingUpdatedAt:
          quote?.observedAt ||
          quote?.retrievedAt?.slice?.(0, 10) ||
          item.pricingUpdatedAt,
      };
      const movement = movementForItem(updated);
      return { ...updated, move: movement?.changePercent ?? null, movement };
    });
    state.movementStatus = state.items.some((item) => movementForItem(item))
      ? "live"
      : planLimited
        ? "plan_required"
        : failed
          ? "error"
          : "unavailable";
    void backfillPurchaseMarketReferences();
  } catch {
    if (!accountRequestIsCurrent(ownerId, loadVersion)) return;
    state.movementStatus = "error";
  }
  renderCollection();
  renderInsights();
  if (state.route === "detail") renderDetail();
  void refreshActionCenter();
}

async function refreshWatchlistPricing() {
  const ownerId = state.session?.user?.id;
  const loadVersion = sessionLoadVersion;
  if (!ownerId) return;
  const unique = [
    ...new Map(
      state.watchlist.filter((item) => item.id).map((item) => [item.id, item]),
    ).values(),
  ];
  if (!unique.length) return;
  state.watchlist = state.watchlist.map((item) => ({
    ...item,
    pricingStatus: "loading",
  }));
  if (state.ledgerView === "watchlist") renderCollection();
  const cardItems = unique.filter((item) => item.cardState !== "sealed");
  const sealedItems = unique.filter((item) => item.cardState === "sealed");
  const lookups = cardItems.map((item) => ({
    clientId: item.id,
    pkmnpricesId: item.externalIds?.pkmnprices || "",
    justtcgId: item.externalIds?.justtcg || "",
    tcgplayerId: item.externalIds?.tcgplayer || "",
    tcgdexId: item.externalIds?.tcgdex || "",
    name: item.name,
    set: item.set,
    number: item.number,
    language: item.language || "en",
  }));
  try {
    const cards = new Map();
    const sealedProducts = new Map();
    const processed = new Set();
    const sealedProcessed = new Set();
    let rateLimited = false;
    let sealedPlanRequired = false;
    for (let start = 0; start < lookups.length; start += 1) {
      if (!accountRequestIsCurrent(ownerId, loadVersion)) return;
      const batch = lookups.slice(start, start + 1);
      const response = await fetch(
        `/api/cards?lookups=${encodeURIComponent(JSON.stringify(batch))}`,
        { headers: providerRequestHeaders() },
      );
      if (response.status === 429) {
        rateLimited = true;
        break;
      }
      if (!response.ok)
        throw new Error(`Watch pricing failed with ${response.status}`);
      const payload = await response.json();
      if (!accountRequestIsCurrent(ownerId, loadVersion)) return;
      batch.forEach((lookup) => processed.add(lookup.clientId));
      (payload.cards || []).forEach((card) =>
        cards.set(card.providerCardId, card),
      );
    }
    for (let start = 0; start < sealedItems.length; start += 1) {
      if (!accountRequestIsCurrent(ownerId, loadVersion)) return;
      if (rateLimited) break;
      const batch = sealedItems.slice(start, start + 1);
      const results = await Promise.allSettled(
        batch.map(async (item) => {
          const id =
            item.externalIds?.pkmnpricesSealed ||
            String(item.id).replace(/^sealed:/, "");
          const response = await fetch(
            `/api/sealed?id=${encodeURIComponent(id)}`,
            { headers: providerRequestHeaders() },
          );
          if (response.status === 403) {
            sealedPlanRequired = true;
            sealedProcessed.add(item.id);
            return null;
          }
          if (response.status === 429) {
            rateLimited = true;
            return null;
          }
          if (!response.ok) throw new Error(String(response.status));
          const payload = await response.json();
          if (!accountRequestIsCurrent(ownerId, loadVersion)) return null;
          sealedProcessed.add(item.id);
          return { item, product: payload.product };
        }),
      );
      results.forEach((result) => {
        if (result.status === "fulfilled" && sealedProductMatches(result.value.item, result.value.product))
          sealedProducts.set(result.value.item.id, result.value.product);
      });
    }
    if (!accountRequestIsCurrent(ownerId, loadVersion)) return;
    state.watchlist = state.watchlist.map((item) => {
      const sealed = item.cardState === "sealed";
      if (sealed && !sealedProcessed.has(item.id))
        return {
          ...item,
          pricingStatus: rateLimited ? "rate_limited" : "error",
        };
      if (!sealed && !processed.has(item.id))
        return {
          ...item,
          pricingStatus: rateLimited ? "rate_limited" : "error",
        };
      const card = sealed ? sealedProducts.get(item.id) : cards.get(item.id);
      if (!card)
        return {
          ...item,
          currentPrice: null,
          referencePrice: null,
          quotes: [],
          pricingStatus:
            sealed && sealedPlanRequired ? "unsupported" : "missing",
          pricingReason:
            sealed && sealedPlanRequired
              ? "provider_plan_required"
              : "provider_match_missing",
        };
      const quote = selectReferenceQuote(
        card.quotes,
        item.variant,
        item.currency || "USD",
        sealed ? {} : item,
      );
      const quoteState = quote ? quoteStatus(quote) : null;
      const capabilityState = capabilityStatusForItem(card, item);
      return {
        ...item,
        externalIds: {
          ...(item.externalIds || {}),
          ...(card.externalIds || {}),
        },
        metadata: card.metadata || item.metadata || null,
        productType: card.productType || item.productType || null,
        currentPrice: quoteState === "live" ? quote.amount : null,
        referencePrice: quote?.amount ?? null,
        quotes: card.quotes || [],
        priceCapabilities: card.capabilities || null,
        priceHistory: card.history || [],
        historyStatus: card.historyStatus || null,
        pricingStatus: quoteState || capabilityState.status,
        pricingReason: quoteState
          ? priceFreshness(quote).reason
          : capabilityState.reason,
        pricingUpdatedAt:
          quote?.observedAt || quote?.retrievedAt?.slice?.(0, 10) || null,
      };
    });
  } catch {
    if (!accountRequestIsCurrent(ownerId, loadVersion)) return;
    state.watchlist = state.watchlist.map((item) => ({
      ...item,
      pricingStatus: "error",
    }));
  }
  if (state.ledgerView === "watchlist") renderCollection();
  renderInsights();
  if (state.route === "detail" && state.detailCard?.watchlistId) {
    const updated = state.watchlist.find(
      (item) => item.watchlistId === state.detailCard.watchlistId,
    );
    if (updated) {
      state.detailCard = { ...updated, price: updated.currentPrice };
      renderDetail();
    }
  }
  void notifyReachedTargets();
  void refreshActionCenter();
}

function renderBusinessReview() {
  if (!$("#businessReview")) return;
  const review = portfolioReview(state.items, state.watchlist);
  const actions = portfolioActions(state.items, state.watchlist);
  const briefButton = $("#portfolioBriefButton");
  const briefResult = $("#portfolioBriefResult");
  briefButton.disabled = !actions.length;
  briefButton.textContent = actions.length
    ? "Explain my priorities"
    : "Nothing needs explanation";
  briefResult.classList.add("hidden");
  briefResult.replaceChildren();
  const signalCount = actions.reduce(
    (sum, action) => sum + action.items.length,
    0,
  );
  if (["ready", "local"].includes(state.actionCenter.status)) {
    const now = Date.now();
    const durableActions = state.actionCenter.items.filter(
      (item) =>
        item.status === "open" ||
        (item.status === "snoozed" &&
          new Date(item.snoozedUntil || 0).getTime() <= now),
    );
    briefButton.disabled = !actions.length;
    briefButton.textContent = actions.length
      ? "Explain verified priorities"
      : "Nothing needs explanation";
    if (!state.items.length && !state.watchlist.length) {
      $("#businessReview").innerHTML =
        '<div class="action-center-empty"><span>Start here</span><strong>Add your first card</strong><small>Search for a card or unopened product, then enter the total paid. Mica will build a simple checklist from your collection.</small><button id="actionCenterAdd" type="button">Find a card →</button></div>';
      $("#actionCenterAdd").addEventListener("click", () => {
        routeTo("scan");
        void openAutoCapture();
      });
      return;
    }
    if (!durableActions.length) {
      $("#businessReview").innerHTML =
        '<div class="action-center-clear"><span>Today</span><strong>You’re caught up</strong><small>No new alerts.</small><b>✓</b></div>';
      return;
    }
    $("#businessReview").innerHTML =
      `<div class="action-center-summary"><span>For you</span><strong>${durableActions.length} action${durableActions.length === 1 ? "" : "s"} need attention</strong></div>${durableActions
        .map((item, index) => {
          const observed = item.observedAt
            ? new Date(item.observedAt).toLocaleString()
            : "time unavailable";
          const confidence = Number.isFinite(Number(item.confidence))
            ? `${Math.round(Number(item.confidence) * 100)}% confidence`
            : "confidence unavailable";
          const controls = item.id
            ? `<div class="action-item-controls"><button type="button" data-action-open="${esc(item.actionKey)}">Open evidence</button><button type="button" data-action-transition="snooze" data-action-key="${esc(item.actionKey)}">Snooze 24h</button><button type="button" data-action-transition="dismiss" data-action-key="${esc(item.actionKey)}">Dismiss</button><button type="button" data-action-transition="complete" data-action-key="${esc(item.actionKey)}">Complete</button></div>`
            : `<div class="action-item-controls"><button type="button" data-action-open="${esc(item.actionKey)}">Open evidence</button><small>Snooze and dismiss aren’t available yet.</small></div>`;
          return `<article class="durable-action ${index === 0 ? "recommended" : ""}"><span>${index === 0 ? "Do this first" : `Next ${index + 1}`}</span><strong>${esc(item.title)}</strong><p>${esc(item.reason)}</p><small>${esc(item.source)} · ${esc(observed)} · ${esc(confidence)}</small><em>${esc(item.suggestedAction)}</em>${controls}</article>`;
        })
        .join("")}`;
    $$("[data-action-open]", $("#businessReview")).forEach((button) =>
      button.addEventListener("click", () => {
        const item = durableActions.find(
          (candidate) => candidate.actionKey === button.dataset.actionOpen,
        );
        if (item) openActionDestination(item);
      }),
    );
    $$("[data-action-transition]", $("#businessReview")).forEach((button) =>
      button.addEventListener(
        "click",
        () =>
          void applyActionTransition(
            button.dataset.actionKey,
            button.dataset.actionTransition,
            button,
          ),
      ),
    );
    return;
  }
  if (!state.items.length && !state.watchlist.length) {
    $("#businessReview").innerHTML =
      '<div class="action-center-empty"><span>Start here</span><strong>Add your first card</strong><small>Search for a card or unopened product, then enter the total paid. Mica will build a simple checklist from your collection.</small><button id="actionCenterAdd" type="button">Find a card →</button></div>';
    $("#actionCenterAdd").addEventListener("click", () => {
      routeTo("scan");
      void openAutoCapture();
    });
    return;
  }
  if (!actions.length) {
    $("#businessReview").innerHTML =
      '<div class="action-center-clear"><span>Today</span><strong>You’re caught up</strong><small>No watched prices have been reached, and no cards need a price or purchase review.</small><b>✓</b></div>';
    return;
  }
  $("#businessReview").innerHTML =
    `<div class="action-center-summary"><span>Today’s checklist</span><strong>${signalCount} item${signalCount === 1 ? "" : "s"} need attention</strong><small>${actions.length} clear next step${actions.length === 1 ? "" : "s"}, with the most useful one first.</small></div>${actions.map((action, index) => `<button type="button" data-business-review="${action.key}" class="${index === 0 ? "recommended" : ""}"><span>${index === 0 ? "Do this first" : `Next ${index + 1}`}</span><strong>${esc(action.title === "Price gaps" ? "Missing prices" : action.title)}</strong><small>${action.items.length} item${action.items.length === 1 ? "" : "s"} · ${esc(action.copy)}</small><b>Review ${action.items.length} →</b></button>`).join("")}`;
  $$("[data-business-review]").forEach((button) =>
    button.addEventListener("click", () => {
      const key = button.dataset.businessReview;
      const items = businessReviewItems(key, review);
      openBusinessReviewQueue(key, items);
    }),
  );
}

function openActionDestination(item) {
  const route = item.destination?.route || "dashboard";
  const id = item.destination?.id || item.subject?.id;
  if (route === "settings") return routeTo("profile");
  if (route === "watchlist") return openWorkspaceShortcut("watchlist");
  if (route === "goals") {
    routeTo("collection", { sidebarTarget: "collection" });
    const goal = state.organization.goals.find(
      (candidate) => candidate.id === id,
    );
    if (goal) requestAnimationFrame(() => openCollectionGoalSheet(goal.id));
    return;
  }
  if (["collection", "grading", "listings"].includes(route)) {
    const position = state.items.find((candidate) => candidate.uid === id);
    if (position) return openCardDetail(position, true);
    return openWorkspaceShortcut(
      route === "listings" ? "seller" : "collection",
    );
  }
  if (route === "sales") return openWorkspaceShortcut("sales");
  routeTo("dashboard", { sidebarTarget: "dashboard" });
}

function applyPendingActionDestination() {
  if (pendingActionDestinationApplied) return;
  const parameters = new URLSearchParams(location.search);
  const route = parameters.get("actionRoute");
  const id = parameters.get("actionId");
  if (!route && !id) return;
  pendingActionDestinationApplied = true;
  const action = state.actionCenter.items.find(
    (candidate) =>
      (!id ||
        candidate.destination?.id === id ||
        candidate.subject?.id === id) &&
      (!route || candidate.destination?.route === route),
  );
  if (action) return openActionDestination(action);
  if (route === "watchlist") return openWorkspaceShortcut("watchlist");
  if (route === "settings") return routeTo("profile");
  if (route === "sales") return openWorkspaceShortcut("sales");
  if (["collection", "goals", "grading", "listings"].includes(route))
    return openWorkspaceShortcut(
      route === "listings" ? "seller" : "collection",
    );
  routeTo("dashboard", { sidebarTarget: "dashboard" });
}

async function applyActionTransition(actionKey, transition, button) {
  const action = state.actionCenter.items.find(
    (candidate) => candidate.actionKey === actionKey,
  );
  if (!action?.id || state.actionCenter.status !== "ready") return;
  button.disabled = true;
  const snoozedUntil =
    transition === "snooze"
      ? new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString()
      : null;
  try {
    await transitionActionItem(supabase, action.id, transition, snoozedUntil);
    const durable = await loadActionCenter(supabase, state.session.user.id);
    state.actionCenter.items = durable.items;
    state.actionCenter.preferences = durable.preferences;
    renderBusinessReview();
    toast(
      transition === "complete"
        ? "Action completed"
        : transition === "dismiss"
          ? "Action dismissed"
          : "Action snoozed for 24 hours",
    );
  } catch (error) {
    button.disabled = false;
    toast(`Could not update the action: ${error.message || "Unknown error"}`);
  }
}

function businessReviewItems(
  key,
  review = portfolioReview(state.items, state.watchlist),
) {
  return key === "listings"
    ? listingReviewItems(state.items)
    : {
        pricing: review.needsPricing,
        "below-cost": review.belowCost,
        older: review.olderInventory,
        targets: review.reachedTargets,
      }[key] || [];
}

function advisorExperienceLevel() {
  return (
    {
      beginner: "beginner",
      familiar: "seller",
      professional: "pro",
    }[state.preferences.experienceLevel] || "beginner"
  );
}

async function requestPortfolioBrief(actions) {
  if (!state.session?.access_token)
    throw new Error("Sign in again before requesting an AI explanation.");
  const response = await fetch("/api/vision", {
    method: "POST",
    headers: {
      Accept: "application/json",
      Authorization: `Bearer ${state.session.access_token}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      mode: "advisor",
      experienceLevel: advisorExperienceLevel(),
      workspace: workspaceMode,
      portfolio: {
        positionCount: state.items.length,
        watchlistCount: state.watchlist.length,
      },
      signals: actions.map((action) => ({
        key: action.key,
        itemCount: action.items.length,
      })),
    }),
  });
  const payload = await response.json().catch(() => ({}));
  if (!response.ok)
    throw new Error(
      payload.error || "AI priorities are temporarily unavailable.",
    );
  return payload.brief;
}

async function explainPortfolioPriorities() {
  const actions = portfolioActions(state.items, state.watchlist);
  if (!actions.length) return;
  const button = $("#portfolioBriefButton");
  const result = $("#portfolioBriefResult");
  button.disabled = true;
  button.textContent = "Preparing explanation…";
  result.classList.remove("hidden");
  result.setAttribute("aria-busy", "true");
  result.innerHTML =
    '<div class="portfolio-brief-loading"><i></i><span>Explaining your checklist without sending card names, prices, notes, or photos…</span></div>';
  try {
    const brief = await requestPortfolioBrief(actions);
    result.innerHTML = `<div class="portfolio-brief-head"><span>AI explanation · based only on this checklist</span><h3>${esc(brief.headline)}</h3><p>${esc(brief.summary)}</p></div><div class="portfolio-brief-priorities">${brief.priorities
      .map((priority, index) => {
        const action = actions.find(
          (candidate) => candidate.key === priority.actionKey,
        );
        if (!action) return "";
        return `<article><span>${index === 0 ? "Start here" : `Then ${index + 1}`}</span><strong>${esc(action.title === "Price gaps" ? "Missing prices" : action.title)}</strong><p>${esc(priority.why)}</p><small>${esc(priority.nextStep)}</small><button type="button" data-advisor-review="${esc(priority.actionKey)}">Open ${action.items.length} item${action.items.length === 1 ? "" : "s"} →</button></article>`;
      })
      .join(
        "",
      )}</div>${brief.caveats.length ? `<p class="portfolio-brief-caveats">${brief.caveats.map((caveat) => esc(caveat)).join(" · ")}</p>` : ""}<p class="portfolio-brief-privacy">No card names, prices, photos, notes, certification numbers, or purchase details were sent. This explanation cannot edit your account.</p>`;
    $$("[data-advisor-review]", result).forEach((reviewButton) =>
      reviewButton.addEventListener("click", () => {
        const key = reviewButton.dataset.advisorReview;
        openBusinessReviewQueue(key, businessReviewItems(key));
      }),
    );
  } catch (error) {
    result.innerHTML = `<div class="portfolio-brief-error"><strong>The automatic checklist still works.</strong><span>${esc(error.message || "AI explanation is unavailable.")}</span><small>If setup is required, connect Vercel AI Gateway; no further app build is needed.</small></div>`;
  } finally {
    result.removeAttribute("aria-busy");
    button.disabled = false;
    button.textContent = "Refresh explanation";
  }
}

function openBusinessReviewQueue(key, items) {
  const config = {
    pricing: {
      title: "Missing prices",
      copy: "Saved cards that do not have a matching price today",
    },
    "below-cost": {
      title: "Worth less than you paid",
      copy: "Cards whose current value is below the amount you paid",
    },
    older: {
      title: "Owned for a long time",
      copy: "Cards you have owned for at least 180 days",
    },
    targets: {
      title: "Reached buy targets",
      copy: "Watchlist prices at or below your target",
    },
    listings: {
      title: "Active listings to repair",
      copy: "Missing details, stale reviews, or asks far from current market",
    },
  }[key];
  if (!config || !items.length) return;
  const rows = items
    .map((item, index) => {
      let metric = "";
      let detail = "";
      const evidence = itemWithPriceEvidence({
        ...item,
        price: item.currentPrice ?? item.price,
      });
      if (key === "pricing") {
        metric = "Needs price";
        detail = esc(
          item.gradingCompany
            ? `${item.gradingCompany} grade ${item.grade}`
            : conditionLabel(item.condition),
        );
      } else if (key === "listings") {
        metric =
          item.askingPrice === null || item.askingPrice === undefined
            ? "Ask missing"
            : money(item.askingPrice, item.currency);
        detail = esc(
          (item.listingReviewReasons || []).join(" · ") ||
            "Listing needs review",
        );
      } else if (key === "below-cost") {
        const value = Number(item.price || 0) * Number(item.quantity || 0);
        const gap = value - Number(item.costBasis || 0);
        metric = `${gap >= 0 ? "+" : ""}${money(gap, item.currency)}`;
        detail = `${money(value, item.currency)} value · ${money(item.costBasis, item.currency)} paid · ${esc(priceProvenanceText(evidence))}`;
      } else if (key === "older") {
        const days = holdingDays(item.purchaseDate);
        metric = days === null ? "Date missing" : `${days} days`;
        detail = `First bought ${esc(item.purchaseDate || "date not recorded")}`;
      } else {
        metric =
          item.currentPrice === null
            ? "Price missing"
            : money(item.currentPrice, item.currency);
        detail = `Your target ${money(item.targetPrice, item.currency)} · ${esc(item.gradingCompany ? `${item.gradingCompany} grade ${item.grade}` : conditionLabel(item.condition))} · ${esc(priceProvenanceText(evidence))}`;
      }
      return `<button class="review-queue-row" type="button" data-review-index="${index}"><img src="${esc(item.thumb || "./icons/icon.svg")}" alt=""><span><strong>${esc(item.name)}</strong><small>${esc(item.set)} · ${esc(item.number)}</small><em>${detail}</em></span><b>${metric}<small>Review →</small></b></button>`;
    })
    .join("");
  openSheet(
    `<div class="sheet-heading"><div><h2 id="sheetTitle">${esc(config.title)}</h2><p>${items.length} item${items.length === 1 ? "" : "s"} · ${esc(config.copy)}</p></div><button class="sheet-close" aria-label="Close">×</button></div><div class="review-queue-list">${rows}</div>${key === "pricing" ? '<div class="sheet-actions"><button class="secondary" id="showAllPriceGaps" type="button">Open filtered library</button></div>' : ""}`,
  );
  $$("[data-review-index]").forEach((button) =>
    button.addEventListener("click", () => {
      const item = items[Number(button.dataset.reviewIndex)];
      closeSheet({ discardHistory: true });
      if (key === "targets") openWatchlistDetail(item);
      else if (key === "listings") openPositionEditSheet(item);
      else openCardDetail(item, true);
    }),
  );
  $("#showAllPriceGaps")?.addEventListener("click", () => {
    closeSheet({ discardHistory: true });
    state.ledgerView = "unpriced";
    state.query = "";
    state.setFilter = "";
    state.conditionFilter = "";
    state.labelFilter = "";
    state.collectionFilter = "";
    state.locationFilter = "";
    $("#collectionSearch").value = "";
    syncTabs();
    renderCollection();
    routeTo("collection");
  });
}

function businessDates(range, today = localIsoDate()) {
  if (range === "all")
    return { from: "0000-01-01", to: today, label: "All time" };
  if (range === "ytd")
    return {
      from: `${today.slice(0, 4)}-01-01`,
      to: today,
      label: "Year to date",
    };
  const days = range === "30d" ? 30 : 90;
  const start = new Date(`${today}T00:00:00Z`);
  start.setUTCDate(start.getUTCDate() - (days - 1));
  return {
    from: start.toISOString().slice(0, 10),
    to: today,
    label: `Last ${days} days`,
  };
}

function renderBusinessSummary() {
  const period = businessDates(state.businessRange);
  const summary = businessSummary(state.items, {
    from: period.from,
    to: period.to,
    currency: "USD",
  });
  if (!summary) return;
  $("#businessReportPeriod").textContent =
    `${period.label} · through ${period.to}`;
  $("#businessExport").disabled = !summary.transactionCount;
  if (!summary.transactionCount) {
    $("#businessReportMetrics").innerHTML =
      '<div class="data-boundary"><strong>No buying or selling in this time period</strong><p>Record purchases and sales to see money in, money out, and money gained here.</p></div>';
    $("#businessReportNote").textContent =
      "This report uses only purchases and sales you record. Changes in card prices are shown separately.";
    return;
  }
  const cashClass = summary.cashFlowMinor >= 0 ? "positive" : "negative";
  const profitClass =
    summary.realizedProfitMinor >= 0 ? "positive" : "negative";
  $("#businessReportMetrics").innerHTML =
    `<div><span>Money received from sales</span><strong>${money(summary.netSalesMinor / 100, summary.currency)}</strong><small>${summary.unitsSold} card${summary.unitsSold === 1 ? "" : "s"} sold · after selling costs</small></div><div><span>Money spent buying cards</span><strong>${money(summary.acquisitionSpendMinor / 100, summary.currency)}</strong><small>${summary.unitsPurchased} card${summary.unitsPurchased === 1 ? "" : "s"} bought</small></div><div class="${cashClass}"><span>Money in minus money out</span><strong>${summary.cashFlowMinor >= 0 ? "+" : ""}${money(summary.cashFlowMinor / 100, summary.currency)}</strong><small>Sales received minus purchases paid</small></div><div class="${profitClass}"><span>${summary.realizedCoverage === summary.saleCount ? "Money gained from sold cards" : "Known money gained from sold cards"}</span><strong>${summary.realizedProfitMinor >= 0 ? "+" : ""}${money(summary.realizedProfitMinor / 100, summary.currency)}</strong><small>Uses what you paid for ${summary.realizedCoverage} of ${summary.saleCount} sales</small></div><div><span>Selling costs</span><strong>${money(summary.sellingCostsMinor / 100, summary.currency)}</strong><small>Total sale prices minus the money you received</small></div><div><span>Recorded activity</span><strong>${summary.transactionCount}</strong><small>${summary.purchaseCount} purchase${summary.purchaseCount === 1 ? "" : "s"} · ${summary.saleCount} sale${summary.saleCount === 1 ? "" : "s"}</small></div>`;
  $("#businessReportNote").textContent = summary.skippedCurrencyCount
    ? `${summary.skippedCurrencyCount} transaction${summary.skippedCurrencyCount === 1 ? " was" : "s were"} excluded to avoid mixing currencies. USD is shown separately.`
    : "Only US-dollar purchases and sales are shown. A card’s price change is not counted as money received until you sell it.";
}

function liquidationInputs() {
  return {
    referencePercent: $("#liquidationReferencePercent")?.value ?? 100,
    feePercent: $("#liquidationFeePercent")?.value ?? 0,
    totalSellingCosts: $("#liquidationSellingCosts")?.value ?? 0,
    currency: "USD",
  };
}

function currentLiquidationPlan() {
  return liquidationPlan(state.items, liquidationInputs());
}

function renderLiquidationPlanner() {
  const output = $("#liquidationOutput");
  const note = $("#liquidationNote");
  const exportButton = $("#liquidationExport");
  if (!output || !note || !exportButton) return;
  const plan = currentLiquidationPlan();
  exportButton.disabled = !plan?.rows.length;
  if (!plan) {
    output.innerHTML =
      '<div class="data-boundary"><strong>Check the scenario inputs</strong><p>Use non-negative percentages and costs. Selling fees must stay below 100%.</p></div>';
    note.textContent = "No estimate is shown until every assumption is valid.";
    return;
  }
  if (!plan.rows.length) {
    output.innerHTML =
      '<div class="data-boundary"><strong>No cards with US-dollar prices yet</strong><p>Add a card and load its matching price to estimate how much money you could keep after selling.</p></div>';
    note.textContent = plan.unpricedUnits
      ? `${plan.unpricedUnits} unpriced card${plan.unpricedUnits === 1 ? " is" : "s are"} excluded, not valued at zero.`
      : "Shown prices are estimates, not guaranteed sale prices.";
    return;
  }
  const profitClass =
    plan.profitMinor === null
      ? ""
      : plan.profitMinor >= 0
        ? "positive"
        : "negative";
  const coverage = portfolioPriceCoverage(state.items, {
    currency: plan.currency,
  });
  const evidenceSummary = `${coverage.automaticCoveragePercent.toFixed(0)}% live automatic coverage · ${coverage.categories.strong.units} strong · ${coverage.categories.moderate.units} moderate · ${coverage.categories.limited.units} limited`;
  output.innerHTML = `<div><span>Current value of included cards</span><strong>${money(plan.referenceValueMinor / 100, plan.currency)}</strong><small>${plan.pricedUnits} priced item${plan.pricedUnits === 1 ? "" : "s"}</small></div><div><span>Expected total sale prices</span><strong>${money(plan.expectedGrossMinor / 100, plan.currency)}</strong><small>Using ${Number(liquidationInputs().referencePercent).toFixed(1)}% of today’s prices</small></div><div><span>Fees and other costs</span><strong>−${money((plan.marketplaceFeesMinor + plan.totalSellingCostsMinor) / 100, plan.currency)}</strong><small>${money(plan.marketplaceFeesMinor / 100, plan.currency)} selling-site fee · ${money(plan.totalSellingCostsMinor / 100, plan.currency)} other</small></div><div class="take-home"><span>Estimated money you keep</span><strong>${money(plan.netProceedsMinor / 100, plan.currency)}</strong><small>Sale prices minus the costs above</small></div><div class="${profitClass}"><span>${plan.profitMinor === null ? "Money gained unavailable" : "Estimated money gained"}</span><strong>${plan.profitMinor === null ? "Add what you paid" : `${plan.profitMinor >= 0 ? "+" : ""}${money(plan.profitMinor / 100, plan.currency)}`}</strong><small>${plan.profitMinor === null ? `${plan.unknownBasisUnits} priced item${plan.unknownBasisUnits === 1 ? " is" : "s are"} missing the amount paid` : "Compared with what you paid for the cards sold"}</small></div><div><span>Lowest sale level that avoids losing money</span><strong>${plan.breakEvenReferencePercent === null ? "—" : `${plan.breakEvenReferencePercent.toFixed(1)}%`}</strong><small>Of today’s shown prices after fees and costs</small></div>`;
  const omissions = [];
  if (plan.unpricedUnits)
    omissions.push(
      `${plan.unpricedUnits} unpriced item${plan.unpricedUnits === 1 ? "" : "s"} excluded`,
    );
  if (plan.skippedCurrencyUnits)
    omissions.push(
      `${plan.skippedCurrencyUnits} non-USD item${plan.skippedCurrencyUnits === 1 ? "" : "s"} kept separate`,
    );
  if (plan.unknownBasisUnits)
    omissions.push(
      `${plan.unknownBasisUnits} item${plan.unknownBasisUnits === 1 ? "" : "s"} missing the amount paid`,
    );
  note.textContent = omissions.length
    ? `${omissions.join(" · ")}. Missing values are never treated as zero. ${evidenceSummary}.`
    : `Every included item has a matching US-dollar price and a recorded amount paid. ${evidenceSummary}. This is still an estimate, not a guaranteed sale.`;
}

function downloadLiquidationScenario() {
  const plan = currentLiquidationPlan();
  if (!plan?.rows.length) return;
  const quote = (value) => `"${String(value ?? "").replaceAll('"', '""')}"`;
  const dollars = (minor) => (Number(minor || 0) / 100).toFixed(2);
  const rows = [
    [
      "Item",
      "Set",
      "Number",
      "Condition or grade",
      "Quantity",
      "Price shown for each",
      "Expected sale each",
      "Expected total sale amount",
      "Estimated percentage fee",
      "Amount originally paid",
    ],
  ];
  plan.rows.forEach((row) =>
    rows.push([
      row.name,
      row.set,
      row.number,
      row.context,
      row.quantity,
      dollars(row.referenceUnitMinor),
      dollars(row.expectedUnitMinor),
      dollars(row.grossMinor),
      dollars(row.feesMinor),
      row.costBasisMinor === null ? "" : dollars(row.costBasisMinor),
    ]),
  );
  rows.push(
    [],
    [
      `Scenario: ${liquidationInputs().referencePercent}% of the shown price`,
      `Fee: ${liquidationInputs().feePercent}%`,
      `Other selling costs: ${dollars(plan.totalSellingCostsMinor)}`,
      `Estimated take-home: ${dollars(plan.netProceedsMinor)}`,
      plan.profitMinor === null
        ? "Estimated money gained: unavailable — amount paid is missing"
        : `Estimated money gained: ${dollars(plan.profitMinor)}`,
    ],
  );
  downloadTextFile(
    rows.map((row) => row.map(quote).join(",")).join("\n"),
    "text/csv;charset=utf-8",
    `mica-take-home-scenario-${localIsoDate()}.csv`,
  );
  toast("Take-home scenario downloaded");
}

function downloadBusinessReport() {
  if (!requireAccountData()) return;
  const period = businessDates(state.businessRange);
  const csv = transactionReportCsv(state.items, {
    from: period.from,
    to: period.to,
    currency: "USD",
  });
  const blob = new Blob([csv], { type: "text/csv;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = `mica-business-${state.businessRange}-${period.to}.csv`;
  link.click();
  URL.revokeObjectURL(url);
  toast("Business report downloaded");
}

function renderInventoryHealth() {
  const health = inventoryHealth(state.items, { currency: "USD" });
  if (!health.totalQuantity) {
    $("#inventoryHealth").innerHTML =
      '<div class="data-boundary"><strong>No cards to review yet</strong><p>Add a purchase and Mica will show whether too much of your money is tied up in a few cards and how long you have owned them.</p></div>';
    $("#inventoryHealthNote").textContent =
      "Cards are counted from your oldest recorded purchase first.";
    return;
  }
  const basisScale = health.totalCostBasis > 0 && !health.unknownBasisQuantity;
  const scaleTotal = basisScale ? health.totalCostBasis : health.totalQuantity;
  const top = health.topPosition;
  const coverage = health.totalQuantity
    ? (health.pricedQuantity / health.totalQuantity) * 100
    : 0;
  const bucketRows = health.buckets
    .filter((bucket) => bucket.quantity > 0)
    .map((bucket) => {
      const scale = basisScale ? bucket.costBasis : bucket.quantity;
      const width = scaleTotal ? Math.max(2, (scale / scaleTotal) * 100) : 0;
      return `<div class="inventory-age-row ${bucket.key === "181+" ? "aged" : ""}"><div><strong>${esc(bucket.label)}</strong><span>${bucket.quantity} card${bucket.quantity === 1 ? "" : "s"} · ${basisScale ? `${money(bucket.costBasis, health.currency)} originally paid` : "purchase amount unavailable"}</span></div><div class="inventory-age-track" aria-label="${esc(bucket.label)} ${width.toFixed(1)} percent of ${basisScale ? "money originally paid" : "cards owned"}"><i style="width:${width}%"></i></div></div>`;
    })
    .join("");
  $("#inventoryHealth").innerHTML =
    `<div class="inventory-health-metrics"><div><span>Card with the most value</span><strong>${top ? `${top.sharePercent.toFixed(1)}%` : "—"}</strong><small>${top ? esc(top.name) : "Needs a price"}</small></div><div><span>Value held in your top 3 cards</span><strong>${health.topThreeSharePercent === null ? "—" : `${health.topThreeSharePercent.toFixed(1)}%`}</strong><small>Of cards with matching prices</small></div><div><span>Cards with matching prices</span><strong>${coverage.toFixed(0)}%</strong><small>${health.pricedQuantity} of ${health.totalQuantity} cards</small></div></div><div class="inventory-aging"><div class="inventory-aging-title"><strong>How long you have owned these cards</strong><span>${basisScale ? "Grouped by what you paid" : "Grouped by card count"}</span></div>${bucketRows}</div>`;
  $("#inventoryHealthNote").textContent = health.unknownBasisQuantity
    ? `${health.unknownBasisQuantity} card${health.unknownBasisQuantity === 1 ? " is" : "s are"} missing the amount paid, so this view uses card count and cannot show money gained.`
    : health.skippedCurrencyPositions
      ? `${health.skippedCurrencyPositions} saved card entr${health.skippedCurrencyPositions === 1 ? "y was" : "ies were"} bought in another currency and kept separate.`
      : "Uses your oldest recorded purchases first. Cards without a matching price are left out instead of being counted as $0.";
}

function renderInsights() {
  const priced = state.items.filter((item) => Number(item.quantity) > 0 && itemValue(item) !== null).length;
  const movements = state.items
    .map((item) => ({ item, movement: movementForItem(item) }))
    .filter((row) => row.movement)
    .sort(
      (left, right) =>
        Math.abs(right.movement.changePercent) -
        Math.abs(left.movement.changePercent),
    );
  const ranked = state.items.filter(item => Number(item.quantity) > 0 && item.status !== "sold")
    .map(item => {
      const performance = itemPurchasePerformance(item, portfolioUnitPrice(item));
      const graded = item.cardState === "graded" || item.gradingCompany;
      const sold = graded ? soldValuationForItem(item) : null;
      const observedAt = sold?.evaluatedAt || (item.gradedValuations || []).filter(point => point.contextValidated && point.verifiedExactSold).at(-1)?.recordedAt;
      const provenance = graded ? sold ? `Completed-sale estimate${observedAt ? ` · ${friendlyObservedAt(observedAt)}` : ""}` : "Exact completed-sale value unavailable" : priceProvenanceText(item);
      return { item, provenance, value: itemValue(item), gain: performance?.change ?? null, gainPercent: performance?.percent ?? null };
    })
    // Different native currencies are grouped, never compared as equal dollars.
    .sort((a, b) => String(a.item.currency || "USD").localeCompare(String(b.item.currency || "USD")) || (b.value ?? -1) - (a.value ?? -1));
  $("#positionRankings").innerHTML = ranked.length
    ? ranked
        .slice(0, 5)
        .map(
          ({ item, provenance, value, gain, gainPercent }) =>
            `<div class="mover"><img src="${esc(item.thumb)}" alt=""><div><strong>${esc(item.name)}</strong><span>${esc(item.gradingCompany ? `${item.gradingCompany} grade ${item.grade}` : conditionLabel(item.condition))} · ${item.quantity} owned</span><small class="price-provenance">${esc(provenance)}</small></div><b>${value === null ? "Unavailable" : `${money(value, item.currency || "USD")}${gain === null ? "" : ` · ${gain >= 0 ? "up " : "down "}${money(Math.abs(gain), item.currency || "USD")}${gainPercent === null ? "" : ` (${gainPercent >= 0 ? "+" : ""}${gainPercent.toFixed(1)}%)`}`}`}</b></div>`,
        )
        .join("")
    : '<div class="data-boundary"><strong>No cards yet</strong><p>Add a card and what you paid to start seeing collection insights.</p></div>';
  renderInventoryHealth();
  const rawCount = state.items
    .filter((item) => item.cardState !== "sealed" && !item.gradingCompany)
    .reduce((sum, item) => sum + Number(item.quantity || 0), 0);
  $("#batchGradingCount").textContent = rawCount
    ? `${rawCount} ungraded card${rawCount === 1 ? "" : "s"} available`
    : "Add an ungraded card to begin";
  const recent = state.items
    .flatMap((item) =>
      (item.transactions || []).map((transaction) => ({ item, transaction })),
    )
    .sort((a, b) => String(b.transaction.date || "").localeCompare(String(a.transaction.date || "")))
    .slice(0, 6);
  $("#recentActivity").innerHTML = recent.length
    ? recent
        .map(({ item, transaction }) => {
          const label =
            transaction.type === "purchase"
              ? "Bought"
              : transaction.type === "sale"
                ? "Sold"
                : transaction.type === "grading_submission"
                  ? "Sent to grading"
                  : transaction.type === "grading_return"
                    ? "Returned graded"
                    : transaction.type === "position_split"
                      ? "Copies separated"
                      : String(transaction.type).replaceAll("_", " ");
          const detail =
            transaction.type === "purchase"
              ? transaction.unitPrice == null
                ? "cost not recorded"
                : `${money(transaction.totalCost, transaction.currency)} total`
              : transaction.type === "sale"
                ? `${money(transaction.netProceeds, transaction.currency)} received after selling costs`
                : transaction.type === "grading_return"
                  ? `${transaction.gradingCompany} grade ${transaction.grade} · ${money(transaction.gradingFees, transaction.currency)} added to what you paid`
                  : transaction.type === "grading_submission"
                    ? `${transaction.gradingCompany || transaction.marketplace} · manual tracking`
                    : transaction.type === "position_split"
                      ? "Original purchase amount moved with the cards · no money moved"
                      : `${transaction.quantity} recorded`;
          return `<div class="mover"><img src="${esc(item.thumb)}" alt=""><div><strong>${esc(label)} ${esc(item.name)}</strong><span>${esc(transaction.date || "Date not recorded")} · ${esc(detail)}</span></div><b>×${transaction.quantity}</b></div>`;
        })
        .join("")
    : '<div class="data-boundary"><strong>No transactions yet</strong><p>Purchases, sales, and grading events will appear here.</p></div>';
  renderBusinessSummary();
  renderBusinessReview();
  renderLiquidationPlanner();
  if (["live", "partial"].includes(state.pricingStatus)) {
    const comparable = movements.filter(
      (row) => row.movement.currency === "USD",
    );
    const prior = comparable.reduce(
      (sum, row) =>
        sum + row.movement.fromAmount * Number(row.item.quantity || 0),
      0,
    );
    const current = comparable.reduce(
      (sum, row) =>
        sum + row.movement.toAmount * Number(row.item.quantity || 0),
      0,
    );
    const change = current - prior;
    if (movements.length) {
      $(".insight-feature").innerHTML =
        `<div class="insight-kicker">Price changes over 30 days</div><strong>${comparable.length ? `${change >= 0 ? "Up " : "Down "}${money(Math.abs(change))}` : `${movements.length} cards with matching past prices`}</strong><span>${comparable.length} card${comparable.length === 1 ? "" : "s"} compared using the number you own now</span><details><summary>How changes are compared</summary><p>Same version, grade, currency and source. Price changes are unrealized until sold.</p></details>`;
    } else {
      $(".insight-feature").innerHTML =
        `<div class="insight-kicker">${state.pricingStatus === "partial" ? "Some prices found" : "Prices connected"}</div><strong>${priced} of ${state.items.length} saved cards have prices</strong><span>${state.items.length - priced} need a matching price</span><div class="unavailable-panel">${state.movementStatus === "loading" ? "Checking past prices for the same cards…" : state.movementStatus === "plan_required" ? "Past prices are ready after PkmnPrices Pro is connected. Today’s prices still work." : state.movementStatus === "error" ? "Past prices could not be refreshed. Today’s collection value is unchanged." : "Price changes appear after Mica has matching prices from at least 30 days apart."}</div>`;
    }
    $("#moversList").innerHTML = movements.length
      ? movements
          .slice(0, 6)
          .map(({ item, movement }) => {
            const context = item.gradingCompany
              ? `${item.gradingCompany} grade ${item.grade}`
              : conditionLabel(item.condition);
            const provider =
              movement.provider === "ebay"
                ? "eBay sold"
                : movement.provider === "tcgplayer"
                  ? "TCGplayer"
                  : movement.provider === "cardmarket"
                    ? "Cardmarket"
                    : movement.provider;
            const dollarChange = movement.toAmount - movement.fromAmount;
            return `<button type="button" class="mover mover-button" data-mover-id="${esc(item.uid)}"><img src="${esc(item.thumb)}" alt=""><div><strong>${esc(item.name)}</strong><span>${esc(context)} · ${esc(provider)} · ${money(movement.fromAmount, movement.currency)} to ${money(movement.toAmount, movement.currency)}</span></div><b class="${dollarChange < 0 ? "negative" : ""}">${dollarChange >= 0 ? "Up " : "Down "}${money(Math.abs(dollarChange), movement.currency)}</b></button>`;
          })
          .join("")
      : '<div class="data-boundary"><strong>Price history is still building</strong><p>A 30-day comparison needs an older price for the same card version and wear level or grade. Mica will not mix different cards.</p></div>';
    $$("[data-mover-id]").forEach((button) =>
      button.addEventListener("click", () =>
        openCardDetail(
          state.items.find((item) => item.uid === button.dataset.moverId),
          true,
        ),
      ),
    );
    return;
  }
  $(".insight-feature").innerHTML =
    `<div class="insight-kicker">Past prices</div><strong>Tracking starts when live prices connect</strong><span>Unavailable prices are never used to claim a real price change.</span><div class="unavailable-panel">Connect matching past prices to see real changes. Mica never turns an estimate into a market trend.</div>`;
  $("#moversList").innerHTML =
    '<div class="data-boundary"><strong>No verified price changes yet</strong><p>Changes appear after Mica has past prices for the same card version, wear level or grade, currency, and source.</p></div>';
}

function tradeItemMarkup(item, side) {
  const max = item.maxQuantity ? ` max="${item.maxQuantity}"` : "";
  const status =
    item.pricingStatus === "manual"
      ? `Owner-entered trade value · ${esc(item.context)} · no market confidence`
      : item.pricingStatus === "live"
        ? `Suggested at ${Number(state.preferences.tradeValuePercent).toFixed(0)}% of reference · ${esc(priceProvenanceText(item))}`
        : item.pricingStatus === "loading"
          ? "Checking matching market price…"
          : `Price needs review · ${esc(item.context)}`;
  return `<article class="trade-item" data-trade-item="${esc(item.tradeId)}" data-trade-item-side="${side}"><img src="${esc(item.thumb || "./icons/icon.svg")}" data-fallback="./icons/icon.svg" alt=""><div class="trade-item-main"><strong>${esc(item.name)}</strong><span>${esc(item.set)} · ${esc(item.number)} · ${esc(item.variant || "Version unknown")}</span><small>${status}</small></div><div class="trade-item-value"><strong>${String(item.valuePerCard).trim() ? money(Number(item.valuePerCard)) : "—"}</strong><label>How many?<input data-trade-quantity type="number" inputmode="numeric" min="1"${max} step="1" value="${item.quantity}"></label><details><summary>Change value</summary><label>Value for each card<div class="money-input"><span>$</span><input data-trade-value type="number" inputmode="decimal" min="0" step="0.01" value="${esc(item.valuePerCard)}" placeholder="0.00"></div></label></details></div><button class="trade-remove" data-trade-remove type="button" aria-label="Remove ${esc(item.name)} from trade">×</button></article>`;
}

function updateTradeSummary() {
  const analysis = tradeAnalysis({
    giveItems: state.trade.give,
    receiveItems: state.trade.receive,
    giveCash: state.trade.giveCash,
    receiveCash: state.trade.receiveCash,
  });
  const verdict = $("#tradeVerdict");
  const copyButton = $("#copyTradeSummary");
  copyButton.disabled =
    !analysis || !state.trade.give.length || !state.trade.receive.length;
  if (!analysis) {
    $("#tradeGiveTotal").textContent = "Check values";
    $("#tradeReceiveTotal").textContent = "Check values";
    verdict.className = "trade-verdict negative";
    verdict.innerHTML =
      '<span>Check the trade values</span><strong>Quantities and values must be zero or higher.</strong><small id="tradeBalanceHelp">Fix the highlighted side, then Mica will compare the deal.</small>';
    return;
  }
  $("#tradeGiveTotal").textContent = money(analysis.giveTotalMinor / 100);
  $("#tradeReceiveTotal").textContent = money(analysis.receiveTotalMinor / 100);
  if (!state.trade.give.length || !state.trade.receive.length) {
    verdict.className = "trade-verdict neutral";
    verdict.innerHTML =
      '<span>Ready when you are</span><strong>Add what you give and what you receive.</strong><small id="tradeBalanceHelp">Mica will compare the exact matching values.</small>';
    return;
  }
  const copy =
    analysis.verdict === "balanced"
      ? {
          tone: "balanced",
          label: "Looks close",
          headline: `The two sides are within ${money(Math.abs(analysis.differenceMinor) / 100)}.`,
        }
      : analysis.verdict === "in_your_favor"
        ? {
            tone: "positive",
            label: "In your favor",
            headline: `You receive about ${money(analysis.differenceMinor / 100)} more.`,
          }
        : {
            tone: "negative",
            label: "In their favor",
            headline: `You give about ${money(Math.abs(analysis.differenceMinor) / 100)} more.`,
          };
  const balance =
    analysis.differenceMinor === 0
      ? "The agreed values are exactly even."
      : `${money(analysis.cashToBalanceMinor / 100)} in cash to ${analysis.cashGoesTo === "them" ? "them" : "you"} would make the totals even.`;
  verdict.className = `trade-verdict ${copy.tone}`;
  verdict.innerHTML = `<span>${copy.label}</span><strong>${copy.headline}</strong><small id="tradeBalanceHelp">${balance}</small>`;
}

function bindTradeItemRows() {
  $$(".trade-item").forEach((row) => {
    const side = row.dataset.tradeItemSide;
    const item = state.trade[side].find(
      (candidate) => candidate.tradeId === row.dataset.tradeItem,
    );
    row
      .querySelector("[data-trade-quantity]")
      .addEventListener("input", (event) => {
        item.quantity = Number(event.target.value);
        updateTradeSummary();
      });
    row
      .querySelector("[data-trade-value]")
      .addEventListener("input", (event) => {
        item.valuePerCard = event.target.value;
        item.pricingStatus = "manual";
        updateTradeSummary();
      });
    row.querySelector("[data-trade-remove]").addEventListener("click", () => {
      state.trade[side] = state.trade[side].filter(
        (candidate) => candidate.tradeId !== item.tradeId,
      );
      renderTrade();
    });
  });
}

function renderTrade() {
  $("#tradeGiveItems").innerHTML = state.trade.give.length
    ? state.trade.give.map((item) => tradeItemMarkup(item, "give")).join("")
    : '<div class="trade-side-empty">No cards added yet.</div>';
  $("#tradeReceiveItems").innerHTML = state.trade.receive.length
    ? state.trade.receive
        .map((item) => tradeItemMarkup(item, "receive"))
        .join("")
    : '<div class="trade-side-empty">No cards added yet.</div>';
  $("#tradeGiveCash").value = state.trade.giveCash;
  $("#tradeReceiveCash").value = state.trade.receiveCash;
  bindTradeItemRows();
  updateTradeSummary();
}

function renderTradeSearchResults() {
  const node = $("#tradeSearchResults");
  if (!node) return;
  const results = state.trade.searchResults;
  node.innerHTML = results.length
    ? results
        .map(
          (item) =>
            `<button class="quick-card-result" type="button" data-trade-card="${esc(item.id)}"><img src="${esc(item.thumb || item.image || "")}" alt=""><span><strong>${esc(item.name)}</strong><small>${esc(item.set)} · ${esc(item.number)}</small><em>${esc(item.variant || "Version unknown")} · ${esc(languageName(item.language || "en"))}</em>${ownedSearchStatus(item)}</span><b>Add</b></button>`,
        )
        .join("")
    : '<div class="find-empty"><strong>No matching cards</strong><span>Try the card name with its set or collector number.</span></div>';
  $$("[data-trade-card]", node).forEach((button) =>
    button.addEventListener("click", () => {
      addTradeCard(
        state.trade.searchResults.find(
          (item) => item.id === button.dataset.tradeCard,
        ),
        state.trade.addingTo,
      );
      closeSheet({ discardHistory: true });
    }),
  );
}

async function priceTradeCard(tradeItem, card) {
  const lookup = [
    {
      clientId: card.id,
      pkmnpricesId: card.externalIds?.pkmnprices || "",
      tcgdexId: card.externalIds?.tcgdex || "",
      name: card.name,
      set: card.set,
      number: card.number,
      language: card.language || "en",
    },
  ];
  try {
    const response = await fetch(
      `/api/cards?lookups=${encodeURIComponent(JSON.stringify(lookup))}`,
      { headers: providerRequestHeaders() },
    );
    if (!response.ok) throw new Error("pricing unavailable");
    const payload = await response.json();
    const priced = payload.cards?.[0];
    const priceContext = tradeItem.gradingCompany
      ? {
          gradingCompany: tradeItem.gradingCompany,
          grade: tradeItem.grade,
        }
      : { condition: tradeItem.condition || "Near Mint" };
    const quote = priced
      ? selectReferenceQuote(
          priced.quotes,
          card.variant,
          tradeItem.currency || "USD",
          priceContext,
        )
      : null;
    const pricing = quotePricingFields(quote, priced, {
      ...card,
      cardState: tradeItem.cardState,
      condition: tradeItem.condition,
      gradingCompany: tradeItem.gradingCompany,
      grade: tradeItem.grade,
    });
    tradeItem.quotes = priced?.quotes || [];
    tradeItem.priceCapabilities = priced?.capabilities || null;
    tradeItem.pricingUpdatedAt =
      quote?.observedAt || quote?.retrievedAt || null;
    const ownerEntered = ["manual", "manual_override"].includes(
      tradeItem.pricingStatus,
    );
    if (
      pricing.price != null &&
      String(tradeItem.valuePerCard).trim() === "" &&
      !ownerEntered
    ) {
      tradeItem.valuePerCard = (
        pricing.price *
        (Number(state.preferences.tradeValuePercent) / 100)
      ).toFixed(2);
      tradeItem.referencePrice = pricing.price;
      tradeItem.price = pricing.price;
      tradeItem.pricingStatus = "live";
    } else if (ownerEntered) {
      tradeItem.referencePrice = pricing.referencePrice;
      tradeItem.price = pricing.price;
      tradeItem.pricingStatus = "manual";
    } else {
      tradeItem.referencePrice = pricing.referencePrice;
      tradeItem.price = pricing.price;
      tradeItem.pricingStatus = pricing.pricingStatus;
    }
  } catch {
    if (!["manual", "manual_override"].includes(tradeItem.pricingStatus))
      tradeItem.pricingStatus = "unavailable";
  }
  if (state.route === "trade") renderTrade();
}

function addTradeCard(card, side = state.trade.addingTo, owned = false) {
  if (!card) return;
  const context = card.gradingCompany
    ? `${card.gradingCompany} ${card.grade}`
    : card.condition
      ? `Ungraded · ${conditionLabel(card.condition)}`
      : "Ungraded · wear not added";
  const pricingSeed = tradePricingSeed(
    card,
    state.preferences.tradeValuePercent,
  );
  const tradeItem = {
    tradeId: crypto.randomUUID(),
    cardId: card.id,
    name: card.name,
    set: card.set,
    number: card.number,
    variant: card.variant,
    context,
    cardState: card.cardState || (card.gradingCompany ? "graded" : "raw"),
    condition: card.gradingCompany ? "Graded" : card.condition || "Near Mint",
    gradingCompany: card.gradingCompany || "",
    grade: card.grade == null ? "" : String(card.grade),
    currency: card.currency || "USD",
    thumb: card.thumb || card.image,
    quantity: 1,
    maxQuantity: owned ? Number(card.quantity) : null,
    valuePerCard: pricingSeed.valuePerCard,
    referencePrice: pricingSeed.referencePrice,
    price: pricingSeed.price,
    quotes: card.quotes || [],
    priceCapabilities: card.priceCapabilities || null,
    pricingUpdatedAt: card.pricingUpdatedAt || null,
    pricingStatus: pricingSeed.pricingStatus,
  };
  state.trade[side].push(tradeItem);
  renderTrade();
  toast(
    `${card.name} added to ${side === "give" ? "You give" : "You receive"}`,
  );
  if (!pricingSeed.canPrefill) void priceTradeCard(tradeItem, card);
}

function openTradeCardPicker(side) {
  state.trade.addingTo = side;
  state.trade.searchResults = [];
  const label = side === "give" ? "What you're giving" : "What they're giving";
  const owned = state.items.filter((item) => item.quantity > 0).slice(0, 8);
  openSheet(
    `<div class="sheet-heading"><div><h2 id="sheetTitle">Add a card</h2><p>${label}</p></div><button class="sheet-close" aria-label="Close">×</button></div><button class="trade-camera" id="tradeCameraButton" type="button">Use camera</button><label class="find-search"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="11" cy="11" r="6.5"/><path d="m16 16 4 4"/></svg><input id="tradeCardSearch" type="search" placeholder="Search name, set, or number" autocomplete="off" aria-label="Search for a card to add to the trade"></label><div class="trade-search-results" id="tradeSearchResults"><div class="find-empty compact"><strong>Find the exact card</strong><span>Mica fills its matching trade estimate when pricing is available.</span></div></div><div class="trade-owned" id="tradeOwned">${owned.length ? `<div class="trade-owned-head"><strong>Your library</strong><span>Tap once to add</span></div><div class="trade-owned-list">${owned.map((item) => `<button type="button" data-trade-owned="${esc(item.uid)}"><img src="${esc(item.thumb)}" alt=""><span><strong>${esc(item.name)}</strong><small>${esc(item.gradingCompany ? `${item.gradingCompany} ${item.grade}` : item.condition)} · ${item.price == null ? "Value needed" : money(item.price)}</small></span><b>Add</b></button>`).join("")}</div>` : ""}</div>`,
  );
  let timer;
  let requestId = 0;
  const input = $("#tradeCardSearch");
  input.addEventListener("input", () => {
    clearTimeout(timer);
    timer = setTimeout(async () => {
      const query = input.value.trim();
      const current = ++requestId;
      if (query.length < 2) {
        state.trade.searchResults = [];
        $("#tradeSearchResults").innerHTML =
          '<div class="find-empty"><strong>Find a card</strong><span>Choose the card that matches the picture and bottom number. Mica fills in a suggested trade value.</span></div>';
        return;
      }
      $("#tradeSearchResults").innerHTML =
        '<div class="searching-cards"><i></i><span>Finding matching cards…</span></div>';
      try {
        const result = await searchCatalog(query, "en", 8);
        if (current !== requestId) return;
        state.trade.searchResults = result.items;
        renderTradeSearchResults();
      } catch {
        if (current !== requestId) return;
        state.trade.searchResults = catalog
          .filter((item) => matchesSearch(item, query))
          .slice(0, 8);
        renderTradeSearchResults();
      }
    }, 220);
  });
  $$("[data-trade-owned]").forEach((button) =>
    button.addEventListener("click", () => {
      addTradeCard(
        state.items.find((item) => item.uid === button.dataset.tradeOwned),
        side,
        true,
      );
      closeSheet({ discardHistory: true });
    }),
  );
  $("#tradeCameraButton").addEventListener("click", () => {
    closeSheet({ discardHistory: true });
    state.visionDestination = "trade";
    void openAutoCapture();
  });
  requestAnimationFrame(() => input.focus());
}

function bindTradeUI() {
  $$("[data-trade-add-side]").forEach((button) =>
    button.addEventListener("click", () =>
      openTradeCardPicker(button.dataset.tradeAddSide),
    ),
  );
  $("#tradeGiveCash").addEventListener("input", (event) => {
    state.trade.giveCash = event.target.value;
    updateTradeSummary();
  });
  $("#tradeReceiveCash").addEventListener("input", (event) => {
    state.trade.receiveCash = event.target.value;
    updateTradeSummary();
  });
  $("#resetTradeButton").addEventListener("click", () => {
    state.trade = {
      give: [],
      receive: [],
      giveCash: "0.00",
      receiveCash: "0.00",
      addingTo: "give",
      searchResults: [],
    };
    renderTrade();
    toast("Trade cleared");
  });
  $("#copyTradeSummary").addEventListener("click", async () => {
    const text = tradeSummary({
      giveItems: state.trade.give,
      receiveItems: state.trade.receive,
      giveCash: state.trade.giveCash,
      receiveCash: state.trade.receiveCash,
    });
    if (!text) {
      toast("Add valid cards and values to both sides first");
      return;
    }
    try {
      await navigator.clipboard.writeText(text);
      toast("Deal summary copied");
    } catch {
      toast("Copy is unavailable in this browser");
    }
  });
}

function syncTabs() {
  $$(".view-tab").forEach((tab) => {
    const active =
      tab.dataset.ledgerView === state.ledgerView &&
      (tab.dataset.conditionFilter || "") === state.conditionFilter;
    tab.classList.toggle("active", active);
    tab.setAttribute("aria-pressed", String(active));
  });
}

export function visibleCollectionViewTabs(root = document) {
  return $$(".view-tab", root).filter(
    (candidate) =>
      !candidate.disabled &&
      candidate.getAttribute("aria-hidden") !== "true" &&
      candidate.getClientRects().length > 0,
  );
}

function toast(message) {
  const node = document.createElement("div");
  node.className = "toast";
  node.textContent = message;
  $("#toastRegion").append(node);
  setTimeout(() => node.remove(), 3000);
}

function intakeQueueStorageKey() {
  const owner = state.session?.user?.id;
  return owner ? `mica:intake-queue:v1:${owner}` : null;
}

function persistIntakeQueue() {
  const key = intakeQueueStorageKey();
  if (!key) return false;
  try {
    if (nativeBuild)
      return nativeRuntime()
        .writeDraft(state.session.user.id, JSON.stringify(state.intakeQueue))
        .then(() => true)
        .catch(() => {
          toast(
            "Your queue is kept in this session only. Restart recovery is unavailable; please retry.",
          );
          return false;
        });
    localStorage.setItem(key, JSON.stringify(state.intakeQueue));
    return true;
  } catch {
    return false;
  }
}

function restoreIntakeQueue(serialized) {
  const key = intakeQueueStorageKey();
  if (!key) return [];
  try {
    const entries = JSON.parse(
      serialized ?? (nativeBuild ? "[]" : localStorage.getItem(key) || "[]"),
    );
    if (!Array.isArray(entries)) return [];
    return entries
      .filter(
        (entry) =>
          entry &&
          typeof entry.key === "string" &&
          entry.card?.name &&
          UUID_PATTERN.test(entry.operationId) &&
          Number.isInteger(entry.quantity) &&
          entry.quantity > 0 &&
          entry.quantity <= 99999 &&
          (!entry.pending ||
            (entry.pending.idempotencyKey === entry.operationId &&
              entry.pending.input &&
              entry.pending.card &&
              (!entry.pending.sealedSave || (entry.pending.ownerId === state.session?.user?.id && entry.pending.input.cardState === "sealed" && entry.pending.input.idempotencyKey === entry.operationId && entry.pending.input.identity && entry.pending.formData && typeof entry.pending.payload === "string")))),
      )
      .slice(0, 50)
      .map((entry) => {
        const card = queuedCatalogCard(entry.card);
        return { ...entry, card, key: intakeQueueKey(card) };
      });
  } catch {
    return [];
  }
}

function queuedCatalogCard(card) {
  const variantOptions = card.variantOptions?.length
    ? card.variantOptions.map((option) =>
        normalizeVariantOption(option, { language: card.language }),
      )
    : [
        card.finish
          ? normalizeVariantOption({
              id: card.variantId,
              label: card.variant,
              finish: card.finish,
              edition: card.edition,
              promoType: card.promoType,
              language: card.language,
            })
          : selectVariantOption(
              { ...card, variantOptions: undefined },
              card.variantId || card.variant,
            ),
      ];
  const snapshot = collectibleIdentitySnapshot(
    { ...card, variantOptions },
    card.variantId || card.variant,
  );
  // Keep structured identity; reparsing a display label can confuse non-holo with holo.
  for (const field of ["image", "thumb"])
    if (!/^(https?:\/\/|\.?\/)/i.test(snapshot[field] || ""))
      snapshot[field] = null;
  return { ...snapshot, id: card.id, provider: card.provider, variantOptions };
}

async function finishQueuedCard(entry, { refreshPending }) {
  state.intakeQueue = state.intakeQueue.filter(
    (candidate) => candidate.key !== entry.key,
  );
  await persistIntakeQueue();
  renderIntakeQueueBar();
  if (!refreshPending) openNextQueuedCard();
}

function openPendingQueuedCard(entry) {
  const owner = state.session?.user?.id;
  if (entry.pending.sealedSave && entry.pending.ownerId !== owner) { toast("Sign in to the original account to finish this save."); return; }
  if (entry.pending.photoRequired && UUID_PATTERN.test(entry.pending.savedItemId)) {
    showSavedScanPhotoRetry(entry.pending.savedItemId, null, owner, sessionLoadVersion, false, {
      ...entry.pending,
      afterSave: result => finishQueuedCard(entry, result),
      afterRefresh: openNextQueuedCard,
    }, false);
    return;
  }
  if (entry.pending.sealedSave) return openSealedPositionSheet(entry.card, { recoveryEntry: entry });
  openSheet(
    `<div class="sheet-heading"><div><h2 id="sheetTitle">Finish adding this card</h2><p>${esc(entry.card.name)} · ${esc(entry.card.set)} · ${esc(entry.pending.input.quantity)} copies</p></div><button class="sheet-close" aria-label="Close">×</button></div><p>${esc(entry.pending.input.variant || entry.card.variant)} · ${esc(languageName(entry.card.language))} · ${entry.pending.acquisitionCostKnown ? `Purchase total ${money(entry.pending.input.totalMinor / 100)}` : "Purchase cost not recorded"}</p><p>The last save wasn’t confirmed. Retry the same details safely before editing this card.</p><p id="queueRetryError" class="form-error" role="alert"></p><div class="sheet-actions"><button class="secondary" id="queueRetryBack">Back to queue</button><button class="primary" id="queueRetrySave">Retry save</button></div>`,
  );
  $("#queueRetryBack").addEventListener("click", openBatchIntakeSheet);
  const button = $("#queueRetrySave");
  const error = $("#queueRetryError");
  button.addEventListener("click", async () => {
    if (button.disabled) return;
    button.disabled = true;
    error.textContent = "";
    try {
      await saveCardAddDraft(
        {
          ...entry.pending,
          queueEntryKey: entry.key,
          queueOwner: owner,
          afterSave: (result) => finishQueuedCard(entry, result),
          afterRefresh: openNextQueuedCard,
        },
        entry.pending.visionAnalysis,
      );
    } catch {
      if (error.isConnected && !entry.pending) {
        openNextQueuedCard();
        return;
      }
      if (error.isConnected)
        error.textContent =
          "Couldn’t confirm the save. Your details are kept. Please retry.";
    } finally {
      if (button.isConnected) button.disabled = false;
    }
  });
}

function intakeQueueKey(card) {
  return [
    card.collectibleId,
    card.variantId,
    card.id,
    card.language,
    card.variant,
  ]
    .filter(Boolean)
    .join("|");
}

function renderIntakeQueueBar() {
  const bar = $("#intakeQueueBar");
  if (!bar) return;
  const quantity = state.intakeQueue.reduce(
    (sum, entry) => sum + Number(entry.quantity || 0),
    0,
  );
  bar.hidden = state.intakeQueue.length === 0;
  $("#intakeQueueCount").textContent =
    `${quantity.toLocaleString()} card${quantity === 1 ? "" : "s"} · ${state.intakeQueue.length.toLocaleString()} exact version${state.intakeQueue.length === 1 ? "" : "s"}`;
}

export async function queueIntakeCard(card) {
  card = queuedCatalogCard(card);
  const key = intakeQueueKey(card);
  const existing = state.intakeQueue.find((entry) => entry.key === key);
  if (existing?.pending) {
    toast("Finish the pending save before adding another copy");
    return;
  }
  if (existing) {
    existing.quantity = Math.min(99_999, existing.quantity + 1);
    syncQueueDraftQuantity(existing);
  } else if (state.intakeQueue.length < 50)
    state.intakeQueue.push({
      key,
      card: queuedCatalogCard(card),
      quantity: 1,
      operationId: crypto.randomUUID(),
    });
  else {
    toast("Review the 50 exact versions already queued first");
    return;
  }
  renderIntakeQueueBar();
  if (!(await persistIntakeQueue()) && intakeQueueStorageKey())
    toast(
      "Queue is available in this tab only. Device storage is unavailable.",
    );
  renderIntakeQueueBar();
  logIngestionEvent({
    sessionId: crypto.randomUUID(),
    channel: "search",
    stage: "queued",
    outcome: "success",
    metadata: {
      queuedCount: state.intakeQueue.length,
      language: card.language || "en",
      candidateStatus: card.identityStatus || "needs_review",
    },
  });
  toast(
    existing
      ? "Added another copy to the review queue"
      : "Added to the review queue",
  );
}

function openNextQueuedCard() {
  const entry = state.intakeQueue[0];
  if (!entry) {
    renderIntakeQueueBar();
    routeTo("scan");
    $("#quickCardSearch")?.focus({ preventScroll: true });
    return;
  }
  if (entry.pending) return openPendingQueuedCard(entry);
  openPositionSheet(entry.card, {
    queueEntryKey: entry.key,
    queueOwner: state.session?.user?.id,
    idempotencyKey: entry.operationId,
    ingestionChannel: "search",
    prefill: entry.editDraft
      ? {
          ...entry.editDraft.input,
          acquisitionCostKnown: entry.editDraft.acquisitionCostKnown,
          acquisitionDateKnown: entry.editDraft.acquisitionDateKnown,
          photoRequired: Boolean(entry.editDraft.photoRequired),
        }
      : { quantity: entry.quantity, cardState: "raw" },
    onCancel: openBatchIntakeSheet,
    afterRefresh: openNextQueuedCard,
    afterSave: (result) => finishQueuedCard(entry, result),
  });
}

function syncQueueDraftQuantity(entry) {
  if (!entry.editDraft) return;
  const input = entry.editDraft.input;
  const breakdown = acquisitionFromTotal(
    (Number(input.totalMinor || 0) / 100).toFixed(2),
    entry.quantity,
  );
  Object.assign(input, breakdown, { quantity: entry.quantity });
}

function queueVariantIsReady(entry) {
  const option = selectVariantOption(
    queuedCatalogCard(entry.card),
    entry.card.variantId || entry.card.variant,
  );
  return Boolean(
    entry.card.name &&
    entry.card.set &&
    entry.card.number &&
    entry.card.language &&
    option.label &&
    !/unknown|unconfirmed|needs confirmation/i.test(option.label),
  );
}

async function saveIntakeBatch() {
  const owner = state.session?.user?.id;
  if (!owner) return;
  const entries = [...state.intakeQueue];
  const errorNode = $("#batchIntakeError");
  const costText = $("#batchIntakeCost").value.trim();
  const date = $("#batchIntakeDate").value;
  const unitMinor = costText ? toMinorUnits(costText) : null;
  if (
    (costText && (!Number.isSafeInteger(unitMinor) || unitMinor < 0)) ||
    (date && date > localIsoDate())
  ) {
    errorNode.textContent =
      "Enter a valid cost and a date no later than today.";
    return;
  }
  if (entries.some((entry) => !entry.pending && !queueVariantIsReady(entry))) {
    errorNode.textContent =
      "Choose the exact version for every card before saving.";
    return;
  }
  try {
    for (const entry of entries) {
      const total = unitMinor == null ? 0 : unitMinor * entry.quantity;
      if (!Number.isSafeInteger(total)) throw new Error("amount");
      const draft = entry.pending ||
        entry.editDraft || {
          card: entry.card,
          input: {
            ...acquisitionFromTotal((total / 100).toFixed(2), entry.quantity),
            quantity: entry.quantity,
            variant: entry.card.variant,
            variantId: entry.card.variantId || "",
            cardState: "raw",
            grader: null,
            grade: null,
            rawCondition: "",
            transactionDate: date || localIsoDate(),
            acquisitionMethod: costText ? "direct_purchase" : "unknown",
            totalAcquisitionCost: costText ? (total / 100).toFixed(2) : "",
          },
          acquisitionCostKnown: unitMinor != null,
          acquisitionDateKnown: Boolean(date),
          idempotencyKey: entry.operationId,
          ingestion: confirmIngestionEnvelope(
            createIngestionEnvelope({
              channel: "search",
              item: entry.card,
              variant: entry.card.variantId || entry.card.variant,
              candidateStatus: entry.card.identityStatus,
            }),
          ),
        };
      if (!entry.pending && !entry.editDraft) entry.batchDraft = draft;
      entry.batchDefaults = { cost: costText, date };
    }
    if (!(await persistIntakeQueue())) throw new Error("storage");
  } catch {
    errorNode.textContent =
      "Couldn’t keep the batch safely on this device. Your queue is unchanged; free some space and retry.";
    return;
  }
  const controls = [
    ...$("#sheetContent").querySelectorAll("button, input, select"),
  ];
  controls.forEach((node) => (node.disabled = true));
  $("#bottomSheet").dataset.lockClose = "true";
  let saved = 0;
  const savedPositionIds = [];
  try {
    for (const entry of entries) {
      if (state.session?.user?.id !== owner) return;
      errorNode.textContent = `Adding ${saved + 1} of ${entries.length}…`;
      if (entry.pending?.savedItemId) { openPendingQueuedCard(entry); return; }
      const draft = entry.pending || entry.editDraft || entry.batchDraft;
      const result = await saveCardAddDraft(
        {
          ...draft,
          queueEntryKey: entry.key,
          queueOwner: owner,
          afterSave: async () => {
            state.intakeQueue = state.intakeQueue.filter(
              (candidate) => candidate.key !== entry.key,
            );
            await persistIntakeQueue();
            renderIntakeQueueBar();
          },
        },
        draft.visionAnalysis,
        {
          closeAfterSave: false,
          focusAfterSave: false,
          refreshAfterSave: false,
          notifyAfterSave: false,
        },
      );
      if (state.session?.user?.id !== owner || result.staleSession) return;
      savedPositionIds.push(result.itemId);
      if (result.photoPending) return;
      saved += 1;
    }
    closeSheet({ discardHistory: true, force: true });
    toast(
      `Added ${saved} card version${saved === 1 ? "" : "s"} to your collection`,
    );
  } catch {
    if (state.session?.user?.id !== owner) return;
    openBatchIntakeSheet();
    $("#batchIntakeCost").value = costText;
    $("#batchIntakeDate").value = date;
    $("#batchIntakeError").textContent =
      `${saved} saved · ${state.intakeQueue.length} remaining. Retry to continue safely.`;
  } finally {
    if (state.session?.user?.id === owner) {
      $("#bottomSheet").dataset.lockClose = "false";
      controls
        .filter((node) => node.isConnected)
        .forEach((node) => (node.disabled = false));
      if (saved) {
        try {
          await reloadPortfolio(null, { backgroundPricing: true, pricingPositionIds: savedPositionIds });
        } catch {
          if (!state.intakeQueue.length && state.session?.user?.id === owner)
            showSavedCollectionRefresh(null, "Cards added to your collection");
        }
      }
    }
  }
}

export function openBatchIntakeSheet() {
  if (!state.intakeQueue.length) {
    renderIntakeQueueBar();
    toast("The review queue is empty");
    return;
  }
  const shared =
    state.intakeQueue.find((entry) => entry.batchDefaults)?.batchDefaults || {};
  const rows = state.intakeQueue
    .map(
      (entry) =>
        `<article class="intake-row" data-intake-row="${esc(entry.key)}"><img src="${esc(entry.card.thumb || entry.card.image || "./icons/icon.svg")}" alt=""><div><strong>${esc(entry.card.name)}</strong><span>${esc(entry.card.set || "Set unavailable")} · ${esc(entry.card.number || "Number unavailable")} · ${esc(languageName(entry.card.language || "en"))} · ${esc(entry.card.variant || "Version needs confirmation")}</span><label class="intake-version">Version <select data-intake-version="${esc(entry.key)}" ${entry.pending ? "disabled" : ""}>${(entry
          .card.variantOptions?.length
          ? entry.card.variantOptions
          : [entry.card.variant || "Unknown"]
        )
          .map((value) => {
            const option = normalizeVariantOption(value, {
              language: entry.card.language,
            });
            return `<option value="${esc(option.id || option.label)}" ${(option.id || option.label) === (entry.card.variantId || entry.card.variant) ? "selected" : ""}>${esc(variantOptionSummary(option))}</option>`;
          })
          .join(
            "",
          )}</select></label></div><div class="intake-row-actions"><label>Copies <input data-intake-quantity="${esc(entry.key)}" type="number" inputmode="numeric" min="1" max="99999" value="${entry.quantity}" ${entry.pending ? "disabled" : ""}></label><button type="button" data-intake-remove="${esc(entry.key)}" ${entry.pending ? "disabled" : ""}>Remove</button></div></article>`,
    )
    .join("");
  openSheet(
    `<div class="sheet-heading"><div><h2 id="sheetTitle">Review card queue</h2><p>Fast catalog queue · confirm each exact version before saving</p></div><button class="sheet-close" aria-label="Close">×</button></div><div class="simple-note">${state.intakeQueue.some((entry) => entry.pending) ? "A card has an unconfirmed save. Retry it before clearing the queue." : "Check the versions and quantities. Purchase details are optional."}</div><div class="intake-list">${rows}</div><details class="intake-more"><summary>Shared purchase details · optional</summary><div class="form-grid"><div class="field"><label for="batchIntakeCost">Paid per card · USD</label><input id="batchIntakeCost" value="${esc(shared.cost || "")}" type="number" min="0" step="0.01" inputmode="decimal" placeholder="Not recorded"></div><div class="field"><label for="batchIntakeDate">Date acquired</label><input id="batchIntakeDate" value="${esc(shared.date || "")}" type="date" max="${localIsoDate()}"></div></div></details><p class="form-error" id="batchIntakeError" role="status" aria-live="polite"></p><div class="sheet-actions"><button class="secondary" id="clearIntakeQueue" type="button" ${state.intakeQueue.some((entry) => entry.pending) ? "disabled" : ""}>Clear queue</button><button class="secondary" id="reviewNextIntake" type="button">Edit individual details</button><button class="primary" id="saveIntakeBatch" type="button">Add these cards</button></div>`,
  );
  $$("[data-intake-quantity]").forEach((input) =>
    input.addEventListener("change", () => {
      const entry = state.intakeQueue.find(
        (candidate) => candidate.key === input.dataset.intakeQuantity,
      );
      const value = Number(input.value);
      if (!entry || !Number.isInteger(value) || value < 1 || value > 99_999) {
        input.value = entry?.quantity || 1;
        return;
      }
      if (entry.pending) return;
      entry.quantity = value;
      syncQueueDraftQuantity(entry);
      persistIntakeQueue();
      renderIntakeQueueBar();
    }),
  );
  $$("[data-intake-remove]").forEach((button) =>
    button.addEventListener("click", () => {
      state.intakeQueue = state.intakeQueue.filter(
        (entry) => entry.pending || entry.key !== button.dataset.intakeRemove,
      );
      renderIntakeQueueBar();
      persistIntakeQueue();
      if (state.intakeQueue.length) openBatchIntakeSheet();
      else closeSheet({ discardHistory: true });
    }),
  );
  $("#clearIntakeQueue").addEventListener("click", () => {
    if (state.intakeQueue.some((entry) => entry.pending)) return;
    state.intakeQueue = [];
    persistIntakeQueue();
    renderIntakeQueueBar();
    closeSheet({ discardHistory: true });
    toast("Review queue cleared · no cards were saved");
  });
  $("#saveIntakeBatch").addEventListener("click", saveIntakeBatch);
  $$("[data-intake-version]").forEach((select) =>
    select.addEventListener("change", () => {
      const entry = state.intakeQueue.find(
        (candidate) => candidate.key === select.dataset.intakeVersion,
      );
      if (!entry || entry.pending) return;
      const option = selectVariantOption(entry.card, select.value);
      const nextCard = {
        ...entry.card,
        variant: option.label,
        variantId: option.id || null,
        finish: option.finish,
        edition: option.edition,
        promoType: option.promoType,
      };
      const key = intakeQueueKey(nextCard);
      if (
        state.intakeQueue.some(
          (candidate) => candidate !== entry && candidate.key === key,
        )
      ) {
        select.value = entry.card.variantId || entry.card.variant;
        toast("That version is already queued. Adjust its copies instead.");
        return;
      }
      entry.card = nextCard;
      entry.key = key;
      if (entry.editDraft) {
        entry.editDraft.card = entry.card;
        entry.editDraft.input.variant = option.label;
        entry.editDraft.input.variantId = option.id || "";
      }
      const cost = $("#batchIntakeCost").value,
        date = $("#batchIntakeDate").value;
      persistIntakeQueue();
      openBatchIntakeSheet();
      $("#batchIntakeCost").value = cost;
      $("#batchIntakeDate").value = date;
      [...document.querySelectorAll("[data-intake-version]")]
        .find((node) => node.dataset.intakeVersion === key)
        ?.focus();
    }),
  );
  $("#reviewNextIntake").addEventListener("click", openNextQueuedCard);
}

function bindQuickCardSearch() {
  const input = $("#quickCardSearch");
  const language = $("#quickSearchLanguage");
  const resultsNode = $("#quickSearchResults");
  const statusNode = $("#quickSearchStatus");
  let timer;
  let requestId = 0;
  let allResults = [];
  let selectedSet = "";
  let showingCached = false;
  let nextCursor = null;
  let provider = "";
  let source = "";
  const setInput = $("#quickSearchSet");
  const showResults = (results) => {
    const restoreFocus = preserveSearchResultFocus(resultsNode);
    if (results) {
      allResults = results;
    }
    const visible = allResults;
    if (statusNode)
      statusNode.textContent = `${showingCached ? "Previously loaded cards · " : ""}${visible.length} matching card${visible.length === 1 ? "" : "s"} shown.`;
    resultsNode.innerHTML = allResults.length
      ? `${showingCached ? '<div class="simple-note">Previously loaded cards · live search is unavailable. <button class="inline-retry" type="button" data-retry-catalog>Try again</button></div>' : ""}${setFilterMarkup(allResults, selectedSet)}${visible
          .map((item) => {
            const owned = ownedCardSummary(item, state.items, {
              exactPrinting: true,
            });
            return `<div class="quick-card-result-wrap"><button class="quick-card-result" type="button" data-quick-card="${esc(item.id)}" aria-label="View ${esc(item.name)} from ${esc(item.set)}, number ${esc(item.number)}${owned.quantity ? `, ${owned.quantity} already owned` : ""}"><img src="${esc(item.thumb || item.image || "")}" alt="${esc(item.name)} card"><span><strong>${esc(item.name)}</strong><small>${esc(item.set || "Set unavailable")} · ${esc(item.number || "Number unavailable")}</small><em>${esc(item.rarity || "Rarity unavailable")} · ${esc(languageName(item.language || language.value))} · ${esc(item.variant || "Version unknown")}</em>${ownedSearchStatus(item)}</span></button><div class="quick-card-actions"><button type="button" data-add-search-card="${esc(item.id)}" aria-label="${owned.quantity ? "Add another" : "Add"} ${esc(item.name)} card">${owned.quantity ? "Add another" : "Add"}</button><button type="button" data-queue-search-card="${esc(item.id)}" aria-label="Queue ${esc(item.name)} for batch review">Queue</button></div></div>`;
          })
          .join("")}`
      : '<div class="find-empty"><strong>No matching cards</strong><span>Try fewer details, verify the language, or search the collector number by itself.</span></div>';
    if (nextCursor)
      resultsNode.insertAdjacentHTML(
        "beforeend",
        '<button type="button" class="secondary catalog-more" data-catalog-more>Load more cards</button>',
      );
    if (provider === "internal")
      resultsNode.insertAdjacentHTML(
        "beforeend",
        '<button type="button" class="secondary catalog-more" data-catalog-broader>Search full catalog</button>',
      );
    resultsNode
      .querySelector("[data-catalog-more]")
      ?.addEventListener("click", () => search(true));
    resultsNode
      .querySelector("[data-catalog-broader]")
      ?.addEventListener("click", () => {
        source = "tcgdex";
        search();
      });
    resultsNode
      .querySelector("[data-retry-catalog]")
      ?.addEventListener("click", search);
    $$("[data-result-set]", resultsNode).forEach((button) =>
      button.addEventListener("click", () => {
        selectedSet = button.dataset.resultSet;
        setInput.value = selectedSet;
        search();
      }),
    );
    $$("[data-quick-card]", resultsNode).forEach((button, index) =>
      button.addEventListener("click", () => openCardDetail(visible[index])),
    );
    $$("[data-add-search-card]", resultsNode).forEach((button, index) =>
      button.addEventListener("click", () => {
        const card = visible[index];
        if (card) openPositionSheet(card, { ingestionChannel: "search" });
      }),
    );
    $$("[data-queue-search-card]", resultsNode).forEach((button, index) =>
      button.addEventListener("click", () => {
        const card = visible[index];
        if (card) queueIntakeCard(card);
      }),
    );
    restoreFocus();
  };
  const syncExamples = () => {
    const examples =
      input.closest("section")?.querySelector(".search-examples") ||
      $(".search-examples");
    if (examples) examples.hidden = input.value.trim().length > 0;
  };
  document.addEventListener("mica:collection-updated", () => {
    if (allResults.length && resultsNode.getAttribute("aria-busy") !== "true") {
      const resultScroll = resultsNode.scrollTop;
      const pageScroll = { top: window.scrollY, left: window.scrollX };
      showResults();
      resultsNode.scrollTop = resultScroll;
      window.scrollTo({ ...pageScroll, behavior: "instant" });
    }
  });
  const search = async (append = false) => {
    const focusBeforeSearch = document.activeElement;
    const restoreSearchFocus = preserveSearchResultFocus(resultsNode);
    append = append === true;
    syncExamples();
    if (!append) {
      allResults = [];
      nextCursor = null;
      provider = "";
    }
    selectedSet = setInput.value.trim();
    clearTimeout(timer);
    const q = input.value.trim();
    const selectedLanguage = language.value;
    const requestedSet = selectedSet;
    const current = ++requestId;
    const isCurrent = () =>
      resultsNode.isConnected &&
      current === requestId &&
      input.value.trim() === q &&
      language.value === selectedLanguage &&
      setInput.value.trim() === requestedSet;
    showingCached = false;
    if (q.length < 2) {
      resultsNode.setAttribute("aria-busy", "false");
      if (statusNode) statusNode.textContent = "Enter at least two characters.";
      resultsNode.innerHTML =
        '<div class="find-empty"><strong>Find the right card</strong><span>Results show the picture, set, and bottom number so you can choose the matching version.</span></div>';
      return;
    }
    resultsNode.setAttribute("aria-busy", "true");
    if (statusNode) statusNode.textContent = "Finding matching cards.";
    if (!append)
      resultsNode.innerHTML =
        '<div class="searching-cards"><i></i><span>Finding matching cards…</span></div>';
    resultsNode
      .querySelector("[data-catalog-more]")
      ?.setAttribute("disabled", "");
    try {
      const result = await searchCatalog(q, selectedLanguage, 12, {
        set: requestedSet,
        cursor: append ? nextCursor : null,
        source,
      });
      if (!isCurrent()) return;
      nextCursor = result.nextCursor;
      provider = result.provider;
      const rows = append ? [...allResults, ...result.items] : result.items;
      showResults([...new Map(rows.map((item) => [item.id, item])).values()]);
      if (
        document.activeElement === document.body ||
        document.activeElement === focusBeforeSearch
      )
        restoreSearchFocus();
    } catch (error) {
      if (!isCurrent()) return;
      if (append) {
        showResults();
        if (statusNode)
          statusNode.textContent =
            "Couldn’t load more cards. Your results are still here. Try again.";
        return;
      }
      logIngestionEvent({
        sessionId: crypto.randomUUID(),
        channel: "search",
        stage: "failed",
        outcome: "failure",
        metadata: {
          language: language.value,
          reason: ingestionFailureReason(error),
          offline: !navigator.onLine,
        },
      });
      const offlineMatches = catalog
        .filter(
          (item) =>
            String(item.language || "").toLowerCase() ===
              selectedLanguage.toLowerCase() &&
            matchesSearch(item, q) &&
            (!requestedSet ||
              item.set?.toLowerCase() === requestedSet.toLowerCase()),
        )
        .slice(0, 12);
      if (offlineMatches.length) {
        showingCached = true;
        showResults(offlineMatches);
      } else {
        if (statusNode)
          statusNode.textContent = "Card search is temporarily unavailable.";
        resultsNode.innerHTML =
          '<div class="find-empty"><strong>Search is temporarily unavailable</strong><span>Your search is still here.</span><button class="secondary" type="button" data-retry-catalog>Try again</button></div>';
        resultsNode
          .querySelector("[data-retry-catalog]")
          .addEventListener("click", search);
      }
    } finally {
      if (isCurrent()) resultsNode.setAttribute("aria-busy", "false");
    }
  };
  const schedule = () => {
    syncExamples();
    allResults = [];
    selectedSet = "";
    nextCursor = null;
    provider = "";
    source = "";
    clearTimeout(timer);
    ++requestId;
    if (input.value.trim().length < 2) {
      void search();
      return;
    }
    resultsNode.setAttribute("aria-busy", "true");
    if (statusNode) statusNode.textContent = "Finding matching cards.";
    resultsNode.innerHTML =
      '<div class="searching-cards"><i></i><span>Finding matching cards…</span></div>';
    timer = setTimeout(search, 220);
  };
  input.addEventListener("input", schedule);
  input.addEventListener("keydown", (event) => {
    if (event.key === "Enter" && !event.isComposing) {
      event.preventDefault();
      void search();
    }
  });
  language.addEventListener("change", () => {
    source = "";
    search();
  });
  setInput.addEventListener("change", () => {
    source = "";
    search();
  });
  $$("[data-search-example]").forEach((button) =>
    button.addEventListener("click", () => {
      input.value = button.dataset.searchExample;
      search();
      input.focus();
    }),
  );
}

function approvedImageProxyPath(value) {
  try {
    const source = new URL(value, location.href);
    if (
      !normalizeCardImageSource(source.href)
    )
      return null;
    const path = `/api/card-image?url=${encodeURIComponent(source.href)}`;
    if (!nativeBuild) return path;
    const origin = nativeRuntime()?.config.apiOrigin;
    return origin ? new URL(path, origin).href : null;
  } catch {
    return null;
  }
}

function imageAttempts(image) {
  try {
    const values = JSON.parse(image.dataset.imageAttempts || "[]");
    return new Set(Array.isArray(values) ? values : []);
  } catch {
    return new Set();
  }
}

function nextImageSource(image) {
  const attempted = imageAttempts(image);
  const current = new URL(image.currentSrc || image.src, location.href).href;
  attempted.add(current);
  const fallback = image.dataset.fallback || "";
  const candidates = [
    approvedImageProxyPath(current),
    approvedImageProxyPath(fallback),
    fallback,
    "./icons/icon.svg",
  ].filter(Boolean);
  const next = candidates.find((candidate) => {
    const absolute = new URL(candidate, location.href).href;
    return !attempted.has(absolute);
  });
  image.dataset.imageAttempts = JSON.stringify([...attempted]);
  if (!next) return false;
  image.src = next;
  return true;
}

async function openGradingResearchConsent() {
  let current = { consented: false };
  try {
    current = await loadGradingResearchConsent(supabase);
  } catch {}
  openSheet(
    `<div class="sheet-heading"><div><h2 id="sheetTitle">Help improve digital grading</h2><p>Optional research consent · separate from normal grading</p></div><button class="sheet-close" aria-label="Close">×</button></div><div class="info-copy"><p><strong>Normal grading does not save your card photos.</strong> Mica keeps measurements, findings, and an image hash after the report is made.</p><p>If you opt in, future prepared grading captures may be stored privately to train and test condition models. When you later provide a verified PSA return, that outcome may be linked to the same physical card for accuracy evaluation. Captures and outcomes are never public or shared with other accounts.</p><p>You can turn this off later. Turning it off deletes retained captures and removes their training eligibility.</p></div><label class="field-choice research-consent-choice"><input id="gradingResearchConsentCheck" type="checkbox" ${current.consented ? "checked" : ""}> I voluntarily allow future grading captures and verified PSA outcomes to be used privately under consent version mica-grading-research-v2.</label><p class="legal-copy">This setting does not make an estimate more accurate today and is not required to use digital grading.</p><p class="form-error" id="gradingResearchConsentError" role="alert"></p><div class="sheet-actions"><button class="secondary" id="gradingResearchCancel" type="button">Cancel</button><button class="primary" id="gradingResearchSave" type="button">Save choice</button></div>`,
  );
  $("#gradingResearchCancel").addEventListener("click", closeSheet);
  $("#gradingResearchSave").addEventListener("click", async () => {
    const button = $("#gradingResearchSave");
    const consented = $("#gradingResearchConsentCheck").checked;
    button.disabled = true;
    button.textContent = "Saving…";
    try {
      await saveGradingResearchConsent(supabase, consented);
      state.gradingResearchConsent = consented;
      $("#gradingResearchConsentState").textContent = consented ? "On" : "Off";
      $("#gradingResearchConsentHelp").textContent = consented
        ? "On · future captures may be retained only when the scan also uses research mode"
        : "Off · normal grading photos are deleted after analysis";
      closeSheet();
      toast(
        consented ? "Research consent turned on" : "Research consent revoked",
      );
    } catch (error) {
      button.disabled = false;
      button.textContent = "Save choice";
      $("#gradingResearchConsentError").textContent =
        error.message || "This choice could not be saved.";
    }
  });
}

